package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.annotation.JsonRootName;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonSerializer;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.module.SimpleModule;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.junit.Test;

import java.io.IOException;

import static org.junit.Assert.*;

public class ObjectMapperValueToTreeWrapRootValueTest {

    @JsonRootName("event")
    public static class Event {
        private Long id;
        private String name;

        public Long getId() {
            return id;
        }

        public void setId(Long id) {
            this.id = id;
        }

        public String getName() {
            return name;
        }

        public void setName(String name) {
            this.name = name;
        }
    }

    @Test
    public void testValueToTreeWithWrapRootValueEnabled() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(SerializationFeature.WRAP_ROOT_VALUE);

        Event event = new Event();
        event.setId(1L);
        event.setName("test");

        JsonNode result = mapper.valueToTree(event);

        // Verify that the root node is an object with a single field named "event"
        assertTrue("Result should be an ObjectNode", result instanceof ObjectNode);
        ObjectNode root = (ObjectNode) result;
        assertEquals("Root should have exactly one field", 1, root.size());
        assertTrue("Root should contain field 'event'", root.has("event"));

        // Verify the nested structure
        JsonNode eventNode = root.get("event");
        assertTrue("'event' field should be an object", eventNode instanceof ObjectNode);
        assertEquals("event.id should be 1", 1, eventNode.get("id").asInt());
        assertEquals("event.name should be 'test'", "test", eventNode.get("name").asText());
    }

    @Test
    public void testValueToTreeWithWrapRootValueDisabled() {
        ObjectMapper mapper = new ObjectMapper();
        mapper.disable(SerializationFeature.WRAP_ROOT_VALUE);

        Event event = new Event();
        event.setId(2L);
        event.setName("example");

        JsonNode result = mapper.valueToTree(event);

        // With WRAP_ROOT_VALUE disabled, the result should be the unwrapped object
        assertTrue("Result should be an ObjectNode", result instanceof ObjectNode);
        ObjectNode root = (ObjectNode) result;
        assertEquals("Root should have two fields", 2, root.size());
        assertTrue("Should have field 'id'", root.has("id"));
        assertTrue("Should have field 'name'", root.has("name"));
        assertEquals("id should be 2", 2, root.get("id").asInt());
        assertEquals("name should be 'example'", "example", root.get("name").asText());
    }

    @Test
    public void testValueToTreeConsistencyWithWriteValueAsString() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(SerializationFeature.WRAP_ROOT_VALUE);

        Event event = new Event();
        event.setId(3L);
        event.setName("consistency");

        JsonNode tree = mapper.valueToTree(event);
        String jsonString = mapper.writeValueAsString(event);

        // Both should produce the same JSON structure
        JsonNode fromString = mapper.readTree(jsonString);

        // Compare via string representation to avoid potential tree comparison issues
        String treeAsString = mapper.writeValueAsString(tree);
        String fromStringAsString = mapper.writeValueAsString(fromString);
        assertEquals("valueToTree and writeValueAsString should produce equivalent JSON", 
                     treeAsString, fromStringAsString);
    }

    // Additional test to cover exception handling in valueToTree()
    @Test(expected = IllegalArgumentException.class)
    public void testValueToTreeWithSerializationFailure() {
        ObjectMapper mapper = new ObjectMapper();

        // Register a module with a serializer that always fails
        SimpleModule module = new SimpleModule();
        module.addSerializer(Event.class, new JsonSerializer<Event>() {
            @Override
            public void serialize(Event value, JsonGenerator gen, SerializerProvider serializers) 
                throws IOException {
                throw new IOException("Simulated serialization failure");
            }
        });
        mapper.registerModule(module);

        Event event = new Event();
        event.setId(4L);
        event.setName("failure-test");

        // This should throw IllegalArgumentException wrapping IOException
        mapper.valueToTree(event);
    }
}

