package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import org.junit.Test;
import static org.junit.Assert.*;

public class TypeParserGuardrailTest {

    private TypeFactory factory = TypeFactory.defaultInstance();
    private TypeParser parser = new TypeParser(factory);

    @Test
    public void testMaxTypeLengthExceeded() {
        StringBuilder sb = new StringBuilder();
        String baseType = "java.util.Map<java.lang.String,java.lang.String>";
        int repeats = 64000 / baseType.length() + 2;
        for (int i = 0; i < repeats; i++) {
            sb.append(baseType);
        }
        String longType = sb.toString();

        try {
            parser.parse(longType);
            fail("Expected IllegalArgumentException for type string exceeding MAX_TYPE_LENGTH");
        } catch (IllegalArgumentException e) {
            String msg = e.getMessage();
            assertTrue("Error message should mention 'too long'", msg.contains("too long"));
            assertTrue("Error message should contain length limit", msg.contains("64000"));
            if (longType.length() > 1000) {
                assertTrue("Error message should indicate truncation", msg.contains("truncated"));
            }
        }
    }

    @Test
    public void testMaxTypeLengthWithinLimit() {
        String baseType = "java.lang.String";
        StringBuilder sb = new StringBuilder(64000);
        sb.append(baseType);
        while (sb.length() < 64000) {
            sb.append(' ');
        }
        String exactLengthType = sb.toString();

        JavaType type = parser.parse(exactLengthType);
        assertEquals("Should parse valid type within length limit", 
                String.class, type.getRawClass());
    }

    @Test
    public void testMaxNestingExceeded() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 1002; i++) {
            sb.append("java.util.List<");
        }
        sb.append("java.lang.String");
        for (int i = 0; i < 1002; i++) {
            sb.append('>');
        }
        String deeplyNested = sb.toString();

        try {
            parser.parse(deeplyNested);
            fail("Expected IllegalArgumentException for type exceeding MAX_TYPE_NESTING");
        } catch (IllegalArgumentException e) {
            String msg = e.getMessage();
            assertTrue("Error message should mention nesting", msg.contains("too deeply nested"));
            assertTrue("Error message should contain nesting limit", msg.contains("1000"));
        }
    }

    @Test
    public void testMaxNestingWithinLimit() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 1000; i++) {
            sb.append("java.util.List<");
        }
        sb.append("java.lang.String");
        for (int i = 0; i < 1000; i++) {
            sb.append('>');
        }
        String maxNested = sb.toString();

        JavaType type = parser.parse(maxNested);
        assertEquals("Outermost type should be List", 
                java.util.List.class, type.getRawClass());
    }

    @Test
    public void testValidTypeParsingStillWorks() {
        JavaType type = parser.parse("java.util.Map<java.lang.String, java.util.List<java.lang.Integer>>");
        assertEquals("Should parse complex generic type", 
                java.util.Map.class, type.getRawClass());

        JavaType simpleType = parser.parse("java.lang.String");
        assertEquals("Should parse simple type", 
                String.class, simpleType.getRawClass());
    }

    @Test
    public void testErrorMessagesTruncation() {
        StringBuilder sb = new StringBuilder();
        String longPrefix = "com.example.verylongpackagename.";
        for (int i = 0; i < 50; i++) {
            sb.append(longPrefix).append("Class").append(i).append("<");
        }
        sb.append("java.lang.String");
        for (int i = 0; i < 50; i++) {
            sb.append('>');
        }
        String longType = sb.toString();

        StringBuilder deeplyNested = new StringBuilder();
        for (int i = 0; i < 1002; i++) {
            deeplyNested.append("java.util.List<");
        }
        deeplyNested.append(longType);
        for (int i = 0; i < 1002; i++) {
            deeplyNested.append('>');
        }
        String testType = deeplyNested.toString();

        try {
            parser.parse(testType);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            String msg = e.getMessage();
            assertTrue("Error message should contain truncation indicator",
                    msg.contains("truncated") || msg.contains("..."));
        }
    }

    @Test
    public void testUnexpectedTokensAfterType() {
        String typeStr = "java.util.List<java.lang.String> extra";
        try {
            parser.parse(typeStr);
            fail("Expected IllegalArgumentException for unexpected tokens");
        } catch (IllegalArgumentException e) {
            String msg = e.getMessage();
            assertTrue("Error message should mention unexpected tokens", 
                    msg.contains("Unexpected tokens after complete type"));
            assertTrue("Error message should show remaining input", 
                    msg.contains("extra"));
        }
    }
}

