package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.CoercionAction;
import com.fasterxml.jackson.databind.cfg.CoercionInputShape;
import com.fasterxml.jackson.databind.type.LogicalType;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.exc.InputCoercionException;
import com.fasterxml.jackson.databind.exc.MismatchedInputException;

import org.junit.Test;
import static org.junit.Assert.*;

import java.io.IOException;
import java.math.BigDecimal;

public class IntToFloatCoercionTest {

    // Helper class to test deserialization into float/double/BigDecimal fields
    static class FloatWrapper {
        public Float value;
    }
    static class DoubleWrapper {
        public Double value;
    }
    static class BigDecimalWrapper {
        public BigDecimal value;
    }
    static class PrimitiveFloatWrapper {
        public float value;
    }
    static class PrimitiveDoubleWrapper {
        public double value;
    }

    @Test
    public void testIntToFloatCoercionFail() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        // Test wrapper Float
        try {
            mapper.readValue("{\"value\": 42}", FloatWrapper.class);
            fail("Should have thrown MismatchedInputException for Float with Fail coercion");
        } catch (MismatchedInputException e) {
            // Expected
            assertTrue(e.getMessage().contains("Integer value (42)"));
        }

        // Test primitive float
        try {
            mapper.readValue("{\"value\": 42}", PrimitiveFloatWrapper.class);
            fail("Should have thrown MismatchedInputException for primitive float with Fail coercion");
        } catch (MismatchedInputException e) {
            // Expected
            assertTrue(e.getMessage().contains("Integer value (42)"));
        }
    }

    @Test
    public void testIntToDoubleCoercionFail() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        // Test wrapper Double
        try {
            mapper.readValue("{\"value\": 42}", DoubleWrapper.class);
            fail("Should have thrown MismatchedInputException for Double with Fail coercion");
        } catch (MismatchedInputException e) {
            // Expected
            assertTrue(e.getMessage().contains("Integer value (42)"));
        }

        // Test primitive double
        try {
            mapper.readValue("{\"value\": 42}", PrimitiveDoubleWrapper.class);
            fail("Should have thrown MismatchedInputException for primitive double with Fail coercion");
        } catch (MismatchedInputException e) {
            // Expected
            assertTrue(e.getMessage().contains("Integer value (42)"));
        }
    }

    @Test
    public void testIntToBigDecimalCoercionFail() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        // Test BigDecimal
        try {
            mapper.readValue("{\"value\": 42}", BigDecimalWrapper.class);
            fail("Should have thrown MismatchedInputException for BigDecimal with Fail coercion");
        } catch (MismatchedInputException e) {
            // Expected
            assertTrue(e.getMessage().contains("Integer value (42)"));
        }
    }

    @Test
    public void testIntToFloatCoercionAsNull() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsNull);

        // Test wrapper Float - should become null
        FloatWrapper fw = mapper.readValue("{\"value\": 42}", FloatWrapper.class);
        assertNull(fw.value);

        // Test primitive float - should become 0.0f
        PrimitiveFloatWrapper pfw = mapper.readValue("{\"value\": 42}", PrimitiveFloatWrapper.class);
        assertEquals(0.0f, pfw.value, 0.0f);
    }

    @Test
    public void testIntToDoubleCoercionAsNull() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsNull);

        // Test wrapper Double - should become null
        DoubleWrapper dw = mapper.readValue("{\"value\": 42}", DoubleWrapper.class);
        assertNull(dw.value);

        // Test primitive double - should become 0.0
        PrimitiveDoubleWrapper pdw = mapper.readValue("{\"value\": 42}", PrimitiveDoubleWrapper.class);
        assertEquals(0.0, pdw.value, 0.0);
    }

    @Test
    public void testIntToBigDecimalCoercionAsNull() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsNull);

        // Test BigDecimal - should become null
        BigDecimalWrapper bdw = mapper.readValue("{\"value\": 42}", BigDecimalWrapper.class);
        assertNull(bdw.value);
    }

    @Test
    public void testIntToFloatCoercionAsEmpty() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsEmpty);

        // Test wrapper Float - should become 0.0f
        FloatWrapper fw = mapper.readValue("{\"value\": 42}", FloatWrapper.class);
        assertEquals(0.0f, fw.value, 0.0f);

        // Test primitive float - should become 0.0f
        PrimitiveFloatWrapper pfw = mapper.readValue("{\"value\": 42}", PrimitiveFloatWrapper.class);
        assertEquals(0.0f, pfw.value, 0.0f);
    }

    @Test
    public void testIntToDoubleCoercionAsEmpty() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsEmpty);

        // Test wrapper Double - should become 0.0
        DoubleWrapper dw = mapper.readValue("{\"value\": 42}", DoubleWrapper.class);
        assertEquals(0.0, dw.value, 0.0);

        // Test primitive double - should become 0.0
        PrimitiveDoubleWrapper pdw = mapper.readValue("{\"value\": 42}", PrimitiveDoubleWrapper.class);
        assertEquals(0.0, pdw.value, 0.0);
    }

    @Test
    public void testIntToBigDecimalCoercionAsEmpty() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsEmpty);

        // Test BigDecimal - should become BigDecimal.ZERO
        BigDecimalWrapper bdw = mapper.readValue("{\"value\": 42}", BigDecimalWrapper.class);
        assertEquals(BigDecimal.ZERO, bdw.value);
    }

    @Test
    public void testIntToFloatCoercionDefault() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Default coercion (not set) should allow integer to float conversion

        // Test wrapper Float - should convert 42 to 42.0f
        FloatWrapper fw = mapper.readValue("{\"value\": 42}", FloatWrapper.class);
        assertEquals(42.0f, fw.value, 0.0f);

        // Test primitive float - should convert 42 to 42.0f
        PrimitiveFloatWrapper pfw = mapper.readValue("{\"value\": 42}", PrimitiveFloatWrapper.class);
        assertEquals(42.0f, pfw.value, 0.0f);
    }

    @Test
    public void testIntToDoubleCoercionDefault() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Default coercion (not set) should allow integer to double conversion

        // Test wrapper Double - should convert 42 to 42.0
        DoubleWrapper dw = mapper.readValue("{\"value\": 42}", DoubleWrapper.class);
        assertEquals(42.0, dw.value, 0.0);

        // Test primitive double - should convert 42 to 42.0
        PrimitiveDoubleWrapper pdw = mapper.readValue("{\"value\": 42}", PrimitiveDoubleWrapper.class);
        assertEquals(42.0, pdw.value, 0.0);
    }

    @Test
    public void testIntToBigDecimalCoercionDefault() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Default coercion (not set) should allow integer to BigDecimal conversion

        // Test BigDecimal - should convert 42 to BigDecimal
        BigDecimalWrapper bdw = mapper.readValue("{\"value\": 42}", BigDecimalWrapper.class);
        assertEquals(new BigDecimal("42"), bdw.value);
    }

    @Test
    public void testFloatTokenStillWorksWithFailCoercion() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        // Float token should still work even with Fail for Integer
        FloatWrapper fw = mapper.readValue("{\"value\": 42.5}", FloatWrapper.class);
        assertEquals(42.5f, fw.value, 0.0f);

        DoubleWrapper dw = mapper.readValue("{\"value\": 42.5}", DoubleWrapper.class);
        assertEquals(42.5, dw.value, 0.0);

        BigDecimalWrapper bdw = mapper.readValue("{\"value\": 42.5}", BigDecimalWrapper.class);
        assertEquals(new BigDecimal("42.5"), bdw.value);
    }

    // Additional test to cover primitive type handling for AsEmpty
    @Test
    public void testIntToPrimitiveFloatCoercionAsEmpty() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, CoercionAction.AsEmpty);

        PrimitiveFloatWrapper pfw = mapper.readValue("{\"value\": 42}", PrimitiveFloatWrapper.class);
        assertEquals(0.0f, pfw.value, 0.0f);
    }
}

