package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.MapperFeature;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.annotation.JsonAutoDetect;
import com.fasterxml.jackson.annotation.PropertyAccessor;
import com.fasterxml.jackson.annotation.JsonProperty;
import org.junit.Test;
import static org.junit.Assert.*;

public class POJOPropertyBuilderCouldDeserializeTest {

    // Test class with one property having only getter (readonly) and another with both getter and setter (readwrite)
    public static class DataB {
        private int readonly = 1;
        private int readwrite = 2;

        public int getReadonly() {
            return readonly;
        }

        public int getReadwrite() {
            return readwrite;
        }

        public void setReadwrite(int value) {
            this.readwrite = value;
        }
    }

    // Test class with a public field (visible) but no getter/setter
    public static class PublicFieldOnly {
        public int value = 42;
    }

    // Test class with a private field (not visible) and no getter/setter
    public static class PrivateFieldOnly {
        @SuppressWarnings("unused")
        private int hidden = 99;
    }

    // Test class with a setter (and getter) - should always be serializable
    public static class WithSetter {
        private int val = 7;

        public int getVal() {
            return val;
        }

        public void setVal(int v) {
            this.val = v;
        }
    }

    // Test class with constructor parameter (and maybe getter)
    public static class WithCtorParam {
        private final int id;

        public WithCtorParam(@JsonProperty("id") int id) {
            this.id = id;
        }

        public int getId() {
            return id;
        }
    }

    @Test
    public void testRequireSettersForGettersWithOnlyGetter() throws Exception {
        // Create mapper with REQUIRE_SETTERS_FOR_GETTERS enabled
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(MapperFeature.REQUIRE_SETTERS_FOR_GETTERS);
        // Ensure only public getters are visible (default visibility)
        mapper.setVisibility(PropertyAccessor.GETTER, JsonAutoDetect.Visibility.PUBLIC_ONLY);
        mapper.setVisibility(PropertyAccessor.SETTER, JsonAutoDetect.Visibility.PUBLIC_ONLY);
        mapper.setVisibility(PropertyAccessor.FIELD, JsonAutoDetect.Visibility.NONE); // fields not visible

        DataB data = new DataB();
        String json = mapper.writeValueAsString(data);

        // With the bug (before patch), readonly would be included because fields were considered
        // even if not visible. After patch, readonly should be excluded because it has no visible setter/field.
        // Expected: {"readwrite":2}
        assertFalse("JSON should not contain 'readonly' property", json.contains("readonly"));
        assertTrue("JSON should contain 'readwrite' property", json.contains("readwrite"));
        assertEquals("{\"readwrite\":2}", json);
    }

    @Test
    public void testCouldDeserializeWithOnlyVisibleField() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(MapperFeature.REQUIRE_SETTERS_FOR_GETTERS);
        // Make fields visible
        mapper.setVisibility(PropertyAccessor.FIELD, JsonAutoDetect.Visibility.PUBLIC_ONLY);
        mapper.setVisibility(PropertyAccessor.GETTER, JsonAutoDetect.Visibility.NONE);
        mapper.setVisibility(PropertyAccessor.SETTER, JsonAutoDetect.Visibility.NONE);

        PublicFieldOnly obj = new PublicFieldOnly();
        String json = mapper.writeValueAsString(obj);

        // The field is visible, so couldDeserialize should return true (via _anyVisible(_fields))
        // and property should be serialized.
        assertTrue("JSON should contain 'value' property", json.contains("value"));
        assertEquals("{\"value\":42}", json);
    }

    @Test
    public void testCouldDeserializeWithNonVisibleField() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(MapperFeature.REQUIRE_SETTERS_FOR_GETTERS);
        // Fields not visible
        mapper.setVisibility(PropertyAccessor.FIELD, JsonAutoDetect.Visibility.NONE);
        mapper.setVisibility(PropertyAccessor.GETTER, JsonAutoDetect.Visibility.NONE);
        mapper.setVisibility(PropertyAccessor.SETTER, JsonAutoDetect.Visibility.NONE);
        // Disable exception for empty beans
        mapper.disable(SerializationFeature.FAIL_ON_EMPTY_BEANS);

        PrivateFieldOnly obj = new PrivateFieldOnly();
        String json = mapper.writeValueAsString(obj);

        // The field is not visible, so couldDeserialize should return false (since _anyVisible(_fields) is false)
        // and property should NOT be serialized.
        assertEquals("{}", json);
    }

    @Test
    public void testCouldDeserializeWithSetter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(MapperFeature.REQUIRE_SETTERS_FOR_GETTERS);
        // Default visibility

        WithSetter obj = new WithSetter();
        String json = mapper.writeValueAsString(obj);

        // Should be serialized because there is a visible setter
        assertTrue(json.contains("val"));
        assertEquals("{\"val\":7}", json);
    }

    @Test
    public void testCouldDeserializeWithConstructorParameter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(MapperFeature.REQUIRE_SETTERS_FOR_GETTERS);

        WithCtorParam obj = new WithCtorParam(123);
        String json = mapper.writeValueAsString(obj);

        // Should be serialized because there is a constructor parameter
        assertTrue(json.contains("id"));
        assertEquals("{\"id\":123}", json);
    }
}

