package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;
import com.fasterxml.jackson.databind.node.NullNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.databind.node.TextNode;
import org.junit.Test;

import static org.junit.Assert.*;

public class JsonNodeWithPropertyTest {
    private static final JsonNodeFactory FACTORY = JsonNodeFactory.instance;

    @Test
    public void testWithObjectPropertyOnObjectNodeMissingProperty() {
        ObjectNode root = FACTORY.objectNode();
        ObjectNode child = root.withObjectProperty("child");
        assertNotNull(child);
        assertTrue(root.has("child"));
        assertSame(child, root.get("child"));
    }

    @Test
    public void testWithObjectPropertyOnObjectNodeNullValue() {
        ObjectNode root = FACTORY.objectNode();
        root.set("child", NullNode.instance);
        ObjectNode child = root.withObjectProperty("child");
        assertNotNull(child);
        assertTrue(root.has("child"));
        assertSame(child, root.get("child"));
        assertFalse(root.get("child").isNull());
    }

    @Test
    public void testWithObjectPropertyOnObjectNodeExistingObject() {
        ObjectNode root = FACTORY.objectNode();
        ObjectNode existingChild = FACTORY.objectNode();
        existingChild.put("inner", "value");
        root.set("child", existingChild);
        ObjectNode child = root.withObjectProperty("child");
        assertNotNull(child);
        assertSame(existingChild, child);
        assertEquals("value", child.get("inner").asText());
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testWithObjectPropertyOnObjectNodeWrongType() {
        ObjectNode root = FACTORY.objectNode();
        root.set("child", FACTORY.textNode("not an object"));
        root.withObjectProperty("child");
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testWithObjectPropertyOnNonObjectNode() {
        ArrayNode arrayNode = FACTORY.arrayNode();
        arrayNode.withObjectProperty("child");
    }

    @Test
    public void testWithArrayPropertyOnObjectNodeMissingProperty() {
        ObjectNode root = FACTORY.objectNode();
        ArrayNode child = root.withArrayProperty("child");
        assertNotNull(child);
        assertTrue(root.has("child"));
        assertSame(child, root.get("child"));
    }

    @Test
    public void testWithArrayPropertyOnObjectNodeNullValue() {
        ObjectNode root = FACTORY.objectNode();
        root.set("child", NullNode.instance);
        ArrayNode child = root.withArrayProperty("child");
        assertNotNull(child);
        assertTrue(root.has("child"));
        assertSame(child, root.get("child"));
        assertFalse(root.get("child").isNull());
    }

    @Test
    public void testWithArrayPropertyOnObjectNodeExistingArray() {
        ObjectNode root = FACTORY.objectNode();
        ArrayNode existingChild = FACTORY.arrayNode();
        existingChild.add("element");
        root.set("child", existingChild);
        ArrayNode child = root.withArrayProperty("child");
        assertNotNull(child);
        assertSame(existingChild, child);
        assertEquals("element", child.get(0).asText());
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testWithArrayPropertyOnObjectNodeWrongType() {
        ObjectNode root = FACTORY.objectNode();
        root.set("child", FACTORY.textNode("not an array"));
        root.withArrayProperty("child");
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testWithArrayPropertyOnNonObjectNode() {
        ArrayNode arrayNode = FACTORY.arrayNode();
        arrayNode.withArrayProperty("child");
    }
}

