        SimpleModule module = new SimpleModule();
        module.addDeserializer(TestObject.class, new UpdatingDeserializer());
        mapper.registerModule(module);

        TestObject existing = new TestObject();
        existing.value = "initial";

        String json = "{\"value\":\"updated\"}";
        TestObject result = mapper.readerForUpdating(existing).readValue(json);

        assertSame("Should return same instance", existing, result);
        assertEquals("Value should be updated", "updated", result.value);
    }

