package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializerProvider;
import org.junit.Test;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;

import static org.junit.Assert.*;

public class SettableAnyPropertyTest {

    // Test for raw Map field
    public static class BeanWithRawMap {
        @JsonAnySetter
        public Map<String, Object> other;
    }

    // Test for HashMap field
    public static class BeanWithHashMap {
        @JsonAnySetter
        public HashMap<String, Object> other;
    }

    // Test for LinkedHashMap field
    public static class BeanWithLinkedHashMap {
        @JsonAnySetter
        public LinkedHashMap<String, Object> other;
    }

    // Test for unsupported Map type (abstract)
    public static abstract class MyAbstractMap<K,V> extends HashMap<K,V> {
        // abstract class cannot be instantiated
    }

    public static class BeanWithAbstractMap {
        @JsonAnySetter
        public MyAbstractMap<String, Object> other;
    }

    @Test
    public void testAnySetterWithNullRawMap() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"name\":\"test\", \"extra\":123}";
        BeanWithRawMap bean = mapper.readValue(json, BeanWithRawMap.class);
        assertNotNull("Map should be initialized", bean.other);
        // Verify concrete map type (LinkedHashMap is default for raw Map)
        assertTrue(bean.other instanceof LinkedHashMap);
        // Should contain both properties from JSON
        assertEquals(2, bean.other.size());
        assertEquals("test", bean.other.get("name"));
        assertEquals(123, bean.other.get("extra"));
    }

    @Test
    public void testAnySetterWithNullHashMap() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"extra\":123}";
        BeanWithHashMap bean = mapper.readValue(json, BeanWithHashMap.class);
        assertNotNull("HashMap should be initialized", bean.other);
        // Verify concrete map type
        assertTrue(bean.other instanceof HashMap);
        assertEquals(1, bean.other.size());
        assertEquals(123, bean.other.get("extra"));
    }

    @Test
    public void testAnySetterWithNullLinkedHashMap() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"extra\":123}";
        BeanWithLinkedHashMap bean = mapper.readValue(json, BeanWithLinkedHashMap.class);
        assertNotNull("LinkedHashMap should be initialized", bean.other);
        // Verify concrete map type
        assertTrue(bean.other instanceof LinkedHashMap);
        assertEquals(1, bean.other.size());
        assertEquals(123, bean.other.get("extra"));
    }

    @Test
    public void testAnySetterWithUnsupportedMapType() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"extra\":123}";
        try {
            mapper.readValue(json, BeanWithAbstractMap.class);
            fail("Should have thrown an exception for unsupported map type");
        } catch (JsonMappingException e) {
            // Verify exception contains expected error message
            String msg = e.getMessage();
            assertTrue("Error message should contain 'Cannot create an instance'",
                    msg.contains("Cannot create an instance"));
            // Verify message mentions the abstract map type
            assertTrue(msg.contains("MyAbstractMap"));
        }
    }

    @Test
    public void testJsonMappingExceptionFromNullDeserializationContext() {
        // Should not throw NullPointerException
        JsonMappingException e = JsonMappingException.from((DeserializationContext) null, "Test message");
        assertNotNull(e);
        // Processor should be null when context is null
        assertNull(e.getProcessor());
    }

    @Test
    public void testJsonMappingExceptionFromNullDeserializationContextWithThrowable() {
        Throwable cause = new RuntimeException("cause");
        JsonMappingException e = JsonMappingException.from((DeserializationContext) null, "Test message", cause);
        assertNotNull(e);
        assertNull(e.getProcessor());
        assertEquals(cause, e.getCause());
    }

    @Test
    public void testJsonMappingExceptionFromNullSerializerProvider() {
        // Should not throw NullPointerException
        JsonMappingException e = JsonMappingException.from((SerializerProvider) null, "Test message");
        assertNotNull(e);
        assertNull(e.getProcessor());
    }

    @Test
    public void testJsonMappingExceptionFromNullSerializerProviderWithThrowable() {
        Throwable cause = new RuntimeException("cause");
        JsonMappingException e = JsonMappingException.from((SerializerProvider) null, "Test message", cause);
        assertNotNull(e);
        assertNull(e.getProcessor());
        assertEquals(cause, e.getCause());
    }
}

