package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonSubTypes;
import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import static org.junit.Assert.*;

public class BeanDeserializerBaseExternalTypeHandlerTest {

    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class Parent {
        public Child child;
    }

    public static class Child {
        @JsonTypeInfo(use = JsonTypeInfo.Id.NAME, include = JsonTypeInfo.As.EXTERNAL_PROPERTY, property = "childType")
        @JsonSubTypes({
                @JsonSubTypes.Type(value = SubChildA.class, name = "A"),
                @JsonSubTypes.Type(value = SubChildB.class, name = "B")
        })
        public SubChild subChild;
    }

    public static abstract class SubChild {
    }

    public static class SubChildA extends SubChild {
        public String valueA;
    }

    public static class SubChildB extends SubChild {
        public int valueB;
    }

    @Test
    public void testExternalTypeHandlerWithJsonIgnoreProperties() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"child\":{\"childType\":\"A\", \"subChild\": {\"valueA\":\"test\"} }}";

        Parent parent = mapper.readValue(json, Parent.class);

        assertNotNull(parent);
        assertNotNull(parent.child);
        assertNotNull(parent.child.subChild);
        assertTrue(parent.child.subChild instanceof SubChildA);
        assertEquals("test", ((SubChildA) parent.child.subChild).valueA);
    }

    @JsonIgnoreProperties({"ignored"})
    public static class TestContainer {
        @JsonTypeInfo(use = JsonTypeInfo.Id.NAME, include = JsonTypeInfo.As.EXTERNAL_PROPERTY, property = "type")
        @JsonSubTypes({
            @JsonSubTypes.Type(value = ConcreteType.class, name = "concrete")
        })
        public BaseType value;
    }

    public static abstract class BaseType {
    }

    public static class ConcreteType extends BaseType {
        public String data;
    }

    @Test
    public void testExternalTypeHandlerPreservedInCopyConstructors() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Fixed JSON structure: type id at same level as value property
        String json = "{\"type\":\"concrete\", \"value\":{\"data\":\"test\"}}";

        TestContainer container = mapper.readValue(json, TestContainer.class);

        assertNotNull(container);
        assertNotNull(container.value);
        assertTrue(container.value instanceof ConcreteType);
        assertEquals("test", ((ConcreteType) container.value).data);
    }

    @JsonIgnoreProperties({"extra"})
    public static class Outer {
        public Inner inner;
    }

    public static class Inner {
        @JsonTypeInfo(use = JsonTypeInfo.Id.NAME, include = JsonTypeInfo.As.EXTERNAL_PROPERTY, property = "innerType")
        @JsonSubTypes({
            @JsonSubTypes.Type(value = InnerImpl.class, name = "impl")
        })
        public InnerBase innerBase;
    }

    public static abstract class InnerBase {
    }

    public static class InnerImpl extends InnerBase {
        public String field;
    }

    @Test
    public void testExternalTypeHandlerWithMultipleLevels() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"inner\":{\"innerType\":\"impl\", \"innerBase\": {\"field\":\"value\"}}}";

        Outer outer = mapper.readValue(json, Outer.class);

        assertNotNull(outer);
        assertNotNull(outer.inner);
        assertNotNull(outer.inner.innerBase);
        assertTrue(outer.inner.innerBase instanceof InnerImpl);
        assertEquals("value", ((InnerImpl) outer.inner.innerBase).field);
    }
}

