package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.core.Version;
import com.fasterxml.jackson.databind.jsontype.TypeResolverBuilder;
import com.fasterxml.jackson.databind.type.SimpleType;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.lang.annotation.Annotation;

/**
 * Tests for {@link PropertyName#merge} and its usage in {@link AnnotationIntrospectorPair}.
 */
public class PropertyNameMergeTest {

    // Unit tests for PropertyName.merge

    @Test
    public void testMergeBothNull() {
        assertNull(PropertyName.merge(null, null));
    }

    @Test
    public void testMergeFirstNull() {
        PropertyName name2 = new PropertyName("simple", "ns");
        assertSame(name2, PropertyName.merge(null, name2));
    }

    @Test
    public void testMergeSecondNull() {
        PropertyName name1 = new PropertyName("simple", "ns");
        assertSame(name1, PropertyName.merge(name1, null));
    }

    @Test
    public void testMergeNonEmptySimpleName() {
        PropertyName name1 = new PropertyName("simple1", null);
        PropertyName name2 = new PropertyName("", "ns2");
        PropertyName merged = PropertyName.merge(name1, name2);
        assertEquals("simple1", merged.getSimpleName());
        assertEquals("ns2", merged.getNamespace());
    }

    @Test
    public void testMergeNonEmptyNamespace() {
        PropertyName name1 = new PropertyName("", "ns1");
        PropertyName name2 = new PropertyName("simple2", null);
        PropertyName merged = PropertyName.merge(name1, name2);
        assertEquals("simple2", merged.getSimpleName());
        assertEquals("ns1", merged.getNamespace());
    }

    @Test
    public void testMergeBothNonEmpty() {
        PropertyName name1 = new PropertyName("simple1", "ns1");
        PropertyName name2 = new PropertyName("simple2", "ns2");
        PropertyName merged = PropertyName.merge(name1, name2);
        assertEquals("simple1", merged.getSimpleName());
        assertEquals("ns1", merged.getNamespace());
    }

    @Test
    public void testMergeEmptyStrings() {
        PropertyName name1 = new PropertyName("", "");
        PropertyName name2 = new PropertyName("simple2", "ns2");
        PropertyName merged = PropertyName.merge(name1, name2);
        assertEquals("simple2", merged.getSimpleName());
        assertEquals("ns2", merged.getNamespace());
    }

    @Test
    public void testMergeUseDefault() {
        PropertyName name1 = PropertyName.USE_DEFAULT;
        PropertyName name2 = new PropertyName("simple2", "ns2");
        PropertyName merged = PropertyName.merge(name1, name2);
        assertEquals("simple2", merged.getSimpleName());
        assertEquals("ns2", merged.getNamespace());
    }

    @Test
    public void testMergeReturnsSameInstanceWhenBothEqual() {
        PropertyName name1 = new PropertyName("simple", "ns");
        PropertyName name2 = new PropertyName("simple", "ns");
        PropertyName merged = PropertyName.merge(name1, name2);
        assertSame(name1, merged);
    }

    @Test
    public void testMergeReturnsName1WhenMergedFieldsMatchName1() {
        PropertyName name1 = new PropertyName("simple", "ns");
        PropertyName name2 = new PropertyName("", null);
        PropertyName merged = PropertyName.merge(name1, name2);
        assertSame(name1, merged);
    }

    @Test
    public void testMergeReturnsName2WhenMergedFieldsMatchName2() {
        PropertyName name1 = new PropertyName("", null);
        PropertyName name2 = new PropertyName("simple", "ns");
        PropertyName merged = PropertyName.merge(name1, name2);
        assertSame(name2, merged);
    }

    // Integration test for AnnotationIntrospectorPair using custom introspectors

    @Test
    public void testAnnotationIntrospectorPairMergesNames() {
        AnnotationIntrospector primary = new AnnotationIntrospector() {
            @Override
            public PropertyName findNameForSerialization(Annotated a) {
                return new PropertyName("", "primaryNS");
            }

            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };

        AnnotationIntrospector secondary = new AnnotationIntrospector() {
            @Override
            public PropertyName findNameForSerialization(Annotated a) {
                return new PropertyName("secondarySimple", null);
            }

            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };

        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(primary, secondary);
        try {
            class Dummy {
                public int value;
            }
            java.lang.reflect.Field field = Dummy.class.getField("value");
            AnnotationMap annMap = new AnnotationMap();
            AnnotatedField annotatedField = new AnnotatedField(null, field, annMap);
            PropertyName result = pair.findNameForSerialization(annotatedField);
            assertNotNull(result);
            assertEquals("secondarySimple", result.getSimpleName());
            assertEquals("primaryNS", result.getNamespace());
        } catch (NoSuchFieldException e) {
            fail("Could not find field: " + e);
        }
    }

    @Test
    public void testAnnotationIntrospectorPairMergesNamesForDeserialization() {
        AnnotationIntrospector primary = new AnnotationIntrospector() {
            @Override
            public PropertyName findNameForDeserialization(Annotated a) {
                return new PropertyName("", "primaryNS");
            }

            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };
        AnnotationIntrospector secondary = new AnnotationIntrospector() {
            @Override
            public PropertyName findNameForDeserialization(Annotated a) {
                return new PropertyName("secondarySimple", null);
            }

            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(primary, secondary);
        try {
            class Dummy {
                public int value;
            }
            java.lang.reflect.Field field = Dummy.class.getField("value");
            AnnotationMap annMap = new AnnotationMap();
            AnnotatedField annotatedField = new AnnotatedField(null, field, annMap);
            PropertyName result = pair.findNameForDeserialization(annotatedField);
            assertNotNull(result);
            assertEquals("secondarySimple", result.getSimpleName());
            assertEquals("primaryNS", result.getNamespace());
        } catch (NoSuchFieldException e) {
            fail("Could not find field: " + e);
        }
    }

    @Test
    public void testAnnotationIntrospectorPairMergesWrapperName() {
        AnnotationIntrospector primary = new AnnotationIntrospector() {
            @Override
            public PropertyName findWrapperName(Annotated a) {
                return new PropertyName("", "primaryNS");
            }

            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };
        AnnotationIntrospector secondary = new AnnotationIntrospector() {
            @Override
            public PropertyName findWrapperName(Annotated a) {
                return new PropertyName("secondarySimple", null);
            }

            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(primary, secondary);
        try {
            class Dummy {
                public int value;
            }
            java.lang.reflect.Field field = Dummy.class.getField("value");
            AnnotationMap annMap = new AnnotationMap();
            AnnotatedField annotatedField = new AnnotatedField(null, field, annMap);
            PropertyName result = pair.findWrapperName(annotatedField);
            assertNotNull(result);
            assertEquals("secondarySimple", result.getSimpleName());
            assertEquals("primaryNS", result.getNamespace());
        } catch (NoSuchFieldException e) {
            fail("Could not find field: " + e);
        }
    }

    @Test
    public void testAnnotationIntrospectorPairMergesRootName() {
        AnnotationIntrospector primary = new AnnotationIntrospector() {
            @Override
            public PropertyName findRootName(AnnotatedClass ac) {
                return new PropertyName("", "primaryNS");
            }

            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };
        AnnotationIntrospector secondary = new AnnotationIntrospector() {
            @Override
            public PropertyName findRootName(AnnotatedClass ac) {
                return new PropertyName("secondarySimple", null);
            }

            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(primary, secondary);

        // Create proper MapperConfig to avoid NullPointerException
        ObjectMapper mapper = new ObjectMapper();
        MapperConfig<?> config = mapper.getDeserializationConfig();
        AnnotatedClass ac = AnnotatedClassResolver.resolve(
                config,
                SimpleType.constructUnsafe(Object.class),
                null
        );

        PropertyName result = pair.findRootName(ac);
        assertNotNull(result);
        assertEquals("secondarySimple", result.getSimpleName());
        assertEquals("primaryNS", result.getNamespace());
    }

    @Test
    public void testAnnotationIntrospectorPairMergesRenameByField() {
        AnnotationIntrospector primary = new AnnotationIntrospector() {
            @Override
            public PropertyName findRenameByField(MapperConfig<?> config, AnnotatedField f, PropertyName implName) {
                return new PropertyName("", "primaryNS");
            }

            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };
        AnnotationIntrospector secondary = new AnnotationIntrospector() {
            @Override
            public PropertyName findRenameByField(MapperConfig<?> config, AnnotatedField f, PropertyName implName) {
                return new PropertyName("secondarySimple", null);
            }

            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(primary, secondary);
        try {
            class Dummy {
                public int value;
            }
            java.lang.reflect.Field field = Dummy.class.getField("value");
            AnnotationMap annMap = new AnnotationMap();
            AnnotatedField annotatedField = new AnnotatedField(null, field, annMap);
            PropertyName result = pair.findRenameByField(null, annotatedField, null);
            assertNotNull(result);
            assertEquals("secondarySimple", result.getSimpleName());
            assertEquals("primaryNS", result.getNamespace());
        } catch (NoSuchFieldException e) {
            fail("Could not find field: " + e);
        }
    }
}

