package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import java.io.IOException;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;

import static org.junit.Assert.*;

public class JsonMappingExceptionNullContextTest {
    static class BeanWithRawMap {
        @JsonAnySetter
        public Map<String, Object> properties = null;
    }

    static class BeanWithHashMap {
        @JsonAnySetter
        public HashMap<String, Object> properties = null;
    }

    static class UnsupportedMap<K, V> extends HashMap<K, V> { }

    static class BeanWithUnsupportedMap {
        @JsonAnySetter
        public UnsupportedMap<String, Object> properties = null;
    }

    @Test
    public void testRawMap() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"name\":\"John\", \"age\":30}";
        BeanWithRawMap bean = mapper.readValue(json, BeanWithRawMap.class);

        assertNotNull(bean.properties);
        assertTrue(bean.properties instanceof LinkedHashMap);
        assertEquals(2, bean.properties.size());
        assertEquals("John", bean.properties.get("name"));
        assertEquals(30, bean.properties.get("age"));
    }

    @Test
    public void testHashMap() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"city\":\"Paris\", \"country\":\"France\"}";
        BeanWithHashMap bean = mapper.readValue(json, BeanWithHashMap.class);

        assertNotNull(bean.properties);
        assertTrue(bean.properties instanceof HashMap);
        assertEquals(2, bean.properties.size());
        assertEquals("Paris", bean.properties.get("city"));
        assertEquals("France", bean.properties.get("country"));
    }

    @Test
    public void testUnsupportedMap() throws IOException {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"key\":\"value\"}";

        try {
            mapper.readValue(json, BeanWithUnsupportedMap.class);
            fail("Should not pass with unsupported Map type");
        } catch (JsonMappingException e) {
            String msg = e.getMessage();
            assertTrue(msg.contains("Cannot create an instance of"));
            assertTrue(msg.contains("UnsupportedMap"));
            assertTrue(msg.contains("for use as \"any-setter\""));
        }
    }

    // Retained null-context tests from original
    @Test
    public void testFromDeserializationContextWithNullContext() {
        JsonMappingException ex = JsonMappingException.from((DeserializationContext) null, "Test message");
        assertNotNull(ex);
        assertEquals("Test message", ex.getMessage());
        assertNull(ex.getProcessor());
    }

    @Test
    public void testFromSerializerProviderWithNullContext() {
        JsonMappingException ex = JsonMappingException.from((SerializerProvider) null, "Test message");
        assertNotNull(ex);
        assertEquals("Test message", ex.getMessage());
        assertNull(ex.getProcessor());
    }
}

