package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.ObjectReader;
import com.fasterxml.jackson.databind.exc.MismatchedInputException;
import com.fasterxml.jackson.databind.module.SimpleModule;
import org.junit.Test;

import java.io.IOException;
import java.util.Date;

import static org.junit.Assert.*;

public class StdDeserializerNestedArrayTest {

    private final ObjectMapper mapper = new ObjectMapper();

    // Helper to create a reader with UNWRAP_SINGLE_VALUE_ARRAYS enabled
    private ObjectReader unwrappingReader() {
        return mapper.reader().with(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
    }

    public enum TestEnum {
        VALUE
    }

    // Custom type to test _deserializeWrappedValue
    public static class Wrapper {
        public String value;
    }

    // Custom deserializer to trigger _deserializeWrappedValue
    public static class WrapperDeserializer extends StdDeserializer<Wrapper> {
        public WrapperDeserializer() {
            super(Wrapper.class);
        }

        @Override
        public Wrapper deserialize(JsonParser p, DeserializationContext ctxt) throws IOException {
            if (p.hasToken(JsonToken.START_ARRAY)) {
                return _deserializeWrappedValue(p, ctxt);
            }
            return null;
        }
    }

    @Test
    public void testBooleanPrimitiveWithNestedArray() throws IOException {
        try {
            unwrappingReader().forType(boolean.class).readValue("[[[true]]]");
            fail("Expected exception for nested array");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("nested Arrays not allowed"));
        } catch (StackOverflowError e) {
            fail("StackOverflowError occurred - indicates missing check for nested arrays");
        }
    }

    @Test
    public void testIntPrimitiveWithNestedArray() throws IOException {
        try {
            unwrappingReader().forType(int.class).readValue("[[[42]]]");
            fail("Expected exception for nested array");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("nested Arrays not allowed"));
        } catch (StackOverflowError e) {
            fail("StackOverflowError occurred - indicates missing check for nested arrays");
        }
    }

    @Test
    public void testLongPrimitiveWithNestedArray() throws IOException {
        try {
            unwrappingReader().forType(long.class).readValue("[[[1234567890123]]]");
            fail("Expected exception for nested array");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("nested Arrays not allowed"));
        } catch (StackOverflowError e) {
            fail("StackOverflowError occurred - indicates missing check for nested arrays");
        }
    }

    @Test
    public void testDoublePrimitiveWithNestedArray() throws IOException {
        try {
            unwrappingReader().forType(double.class).readValue("[[[3.14]]]");
            fail("Expected exception for nested array");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("nested Arrays not allowed"));
        } catch (StackOverflowError e) {
            fail("StackOverflowError occurred - indicates missing check for nested arrays");
        }
    }

    @Test
    public void testDateWithNestedArray() throws IOException {
        try {
            unwrappingReader().forType(Date.class).readValue("[[[\"2022-01-01T00:00:00Z\"]]]");
            fail("Expected exception for nested array");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("nested Arrays not allowed"));
        } catch (StackOverflowError e) {
            fail("StackOverflowError occurred - indicates missing check for nested arrays");
        }
    }

    @Test
    public void testEnumWithNestedArray() throws IOException {
        try {
            unwrappingReader().forType(TestEnum.class).readValue("[[[\"VALUE\"]]]");
            fail("Expected exception for nested array");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("nested Arrays not allowed"));
        } catch (StackOverflowError e) {
            fail("StackOverflowError occurred - indicates missing check for nested arrays");
        }
    }

    @Test
    public void testWrapperWithNestedArray() throws IOException {
        // Register custom deserializer
        SimpleModule module = new SimpleModule();
        module.addDeserializer(Wrapper.class, new WrapperDeserializer());
        mapper.registerModule(module);

        try {
            unwrappingReader().forType(Wrapper.class).readValue("[[[{}]]]");
            fail("Expected exception for nested array");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("nested Arrays not allowed"));
        } catch (StackOverflowError e) {
            fail("StackOverflowError occurred - indicates missing check for nested arrays");
        }
    }

    @Test
    public void testSingleUnwrapStillWorks() throws IOException {
        // Ensure that normal unwrapping still works
        boolean b = unwrappingReader().forType(boolean.class).readValue("[true]");
        assertTrue(b);

        int i = unwrappingReader().forType(int.class).readValue("[42]");
        assertEquals(42, i);

        long l = unwrappingReader().forType(long.class).readValue("[123]");
        assertEquals(123L, l);

        double d = unwrappingReader().forType(double.class).readValue("[3.14]");
        assertEquals(3.14, d, 0.001);

        Date date = unwrappingReader().forType(Date.class).readValue("[\"2022-01-01T00:00:00Z\"]");
        assertNotNull(date);

        TestEnum e = unwrappingReader().forType(TestEnum.class).readValue("[\"VALUE\"]");
        assertEquals(TestEnum.VALUE, e);
    }
}

