package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.CoercionAction;
import com.fasterxml.jackson.databind.cfg.CoercionInputShape;
import com.fasterxml.jackson.databind.type.LogicalType;
import org.junit.Test;

import java.io.IOException;
import java.math.BigDecimal;

import static org.junit.Assert.*;

public class NumberDeserializersCoercionTest {

    // Helper method to create ObjectMapper with coercion config for both Integer and String
    private ObjectMapper mapperWithCoercion(CoercionAction action) {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
                .setCoercion(CoercionInputShape.Integer, action)
                .setCoercion(CoercionInputShape.String, action);
        return mapper;
    }

    // Test for primitive float with integer token
    @Test
    public void testFloatPrimitiveCoercionFail() throws IOException {
        ObjectMapper mapper = mapperWithCoercion(CoercionAction.Fail);
        try {
            mapper.readValue("123", float.class);
            fail("Expected JsonMappingException for integer to float with CoercionAction.Fail");
        } catch (JsonMappingException e) {
            assertTrue(e.getMessage().contains("Integer value"));
        }
    }

    @Test
    public void testFloatPrimitiveCoercionAsNull() throws IOException {
        ObjectMapper mapper = mapperWithCoercion(CoercionAction.AsNull);
        float value = mapper.readValue("456", float.class);
        assertEquals(0.0f, value, 0.0f);
    }

    @Test
    public void testFloatPrimitiveCoercionAsEmpty() throws IOException {
        ObjectMapper mapper = mapperWithCoercion(CoercionAction.AsEmpty);
        float value = mapper.readValue("789", float.class);
        assertEquals(0.0f, value, 0.0f);
    }

    // Test for wrapper Float with integer token
    @Test
    public void testFloatWrapperCoercionFail() throws IOException {
        ObjectMapper mapper = mapperWithCoercion(CoercionAction.Fail);
        try {
            mapper.readValue("123", Float.class);
            fail("Expected JsonMappingException for integer to Float with CoercionAction.Fail");
        } catch (JsonMappingException e) {
            assertTrue(e.getMessage().contains("Integer value"));
