    public void testDoublePrimitiveCoercionAsEmpty() throws IOException {
        ObjectMapper mapper = mapperWithCoercion(CoercionAction.AsEmpty);
        double value = mapper.readValue("789", double.class);
        assertEquals(0.0, value, 0.0);
    }

    // Test for wrapper Double with integer token
