    public void testDoubleWrapperCoercionFail() throws IOException {
        ObjectMapper mapper = mapperWithCoercion(CoercionAction.Fail);
        try {
            mapper.readValue("123", Double.class);
            fail("Expected JsonMappingException for integer to Double with CoercionAction.Fail");
        } catch (JsonMappingException e) {
            assertTrue(e.getMessage().contains("Integer value"));
        }
