    private <T> void testPrimitiveWithDeeplyNestedArray(Class<T> targetType, Object value, StdDeserializer<T> deserializer) throws IOException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

        SimpleModule module = new SimpleModule();
        module.addDeserializer(targetType, deserializer);
        mapper.registerModule(module);

        String json = String.format("[[[%s]]]", value);
        try {
            mapper.readValue(json, targetType);
            fail("Expected exception for nested arrays with UNWRAP_SINGLE_VALUE_ARRAYS");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("nested Arrays not allowed"));
            assertTrue(e.getMessage().contains("UNWRAP_SINGLE_VALUE_ARRAYS"));
