import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import org.junit.Test;

import java.util.List;
import java.util.Map;

import static org.junit.Assert.*;

public class Issue2543Test {

    // Test class with a delegating creator
    public static class DataWithDelegatingCreator {
        private final String foo;
        private final String bar;

        private DataWithDelegatingCreator(String foo, String bar) {
            this.foo = foo;
            this.bar = bar;
        }

        @JsonCreator(mode = JsonCreator.Mode.DELEGATING)
        public static DataWithDelegatingCreator fromBuilder(Builder builder) {
            return new DataWithDelegatingCreator(builder.foo, builder.bar);
        }

        public String getFoo() { return foo; }
        public String getBar() { return bar; }

        // Builder class
        public static class Builder {
            @JsonProperty
            private String foo;
            @JsonProperty
            private String bar;

            public Builder withFoo(String f) { this.foo = f; return this; }
            public Builder withBar(String b) { this.bar = b; return this; }
        }
    }

    // Test class with a properties-based creator (for comparison)
    public static class DataWithPropertiesCreator {
        private final String foo;
        private final String bar;

        @JsonCreator(mode = JsonCreator.Mode.PROPERTIES)
        public DataWithPropertiesCreator(@JsonProperty("foo") String foo,
                                         @JsonProperty("bar") String bar) {
            this.foo = foo;
            this.bar = bar;
        }

        public String getFoo() { return foo; }
        public String getBar() { return bar; }
    }

    @Test
    public void testDelegatingCreatorParameterNotIncludedAsProperty() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        MapperConfig<?> config = mapper.getDeserializationConfig();
        JavaType type = mapper.constructType(DataWithDelegatingCreator.class);
        AnnotatedClass ac = AnnotatedClassResolver.resolve(config, type, config);

        // Get AccessorNamingStrategy.Provider and obtain the strategy
        AccessorNamingStrategy.Provider provider = config.getAccessorNaming();
        AccessorNamingStrategy naming = provider.forPOJO(config, ac);
        POJOPropertiesCollector collector = new POJOPropertiesCollector(
                config, false, type, ac, naming);
        collector.collectAll();

        Map<String, POJOPropertyBuilder> props = collector.getPropertyMap();

        // The delegating creator parameter "builder" should NOT be in the properties
        assertFalse("Delegating creator parameter should not be a property",
                props.containsKey("builder"));
    }

    @Test
    public void testPropertiesCreatorParametersAreIncluded() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        MapperConfig<?> config = mapper.getDeserializationConfig();
        JavaType type = mapper.constructType(DataWithPropertiesCreator.class);
        AnnotatedClass ac = AnnotatedClassResolver.resolve(config, type, config);

        // Get AccessorNamingStrategy.Provider and obtain the strategy
        AccessorNamingStrategy.Provider provider = config.getAccessorNaming();
        AccessorNamingStrategy naming = provider.forPOJO(config, ac);
        POJOPropertiesCollector collector = new POJOPropertiesCollector(
                config, false, type, ac, naming);
        collector.collectAll();

        Map<String, POJOPropertyBuilder> props = collector.getPropertyMap();

        // Properties-based creator parameters should be included
        assertTrue("Properties creator parameter 'foo' should be a property",
                props.containsKey("foo"));
        assertTrue("Properties creator parameter 'bar' should be a property",
                props.containsKey("bar"));
    }

    @Test
    public void testBeanDescriptionForDelegatingCreator() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        BeanDescription beanDesc = mapper.getSerializationConfig()
                .introspect(mapper.constructType(DataWithDelegatingCreator.class));

        List<BeanPropertyDefinition> properties = beanDesc.findProperties();

        // The delegating creator parameter should not appear as a property
        for (BeanPropertyDefinition prop : properties) {
            String name = prop.getName();
            assertFalse("Delegating creator parameter 'builder' should not be a property",
                    "builder".equals(name));
        }

        // Serialization should include getter-based properties
        assertEquals("Should have 2 properties in serialization", 2, properties.size());
        assertTrue("Should contain 'foo' property", properties.stream()
                .anyMatch(p -> "foo".equals(p.getName())));
        assertTrue("Should contain 'bar' property", properties.stream()
                .anyMatch(p -> "bar".equals(p.getName())));
    }

    @Test
    public void testDelegatingCreatorWithExplicitParameterName() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Test deserialization
        String json = "{\"foo\": \"testFoo\", \"bar\": \"testBar\"}";
        DataWithDelegatingCreator result = mapper.readValue(json, DataWithDelegatingCreator.class);

        assertNotNull(result);
        assertEquals("testFoo", result.getFoo());
        assertEquals("testBar", result.getBar());

        // Verify serialization properties
        BeanDescription beanDesc = mapper.getSerializationConfig()
                .introspect(mapper.constructType(DataWithDelegatingCreator.class));

        List<BeanPropertyDefinition> properties = beanDesc.findProperties();
        // Serialization should have 2 properties (getters)
        assertEquals("Should have 2 properties in serialization", 2, properties.size());
        // Ensure no creator parameter appears as property
        for (BeanPropertyDefinition prop : properties) {
            assertNotEquals("builder", prop.getName());
        }
    }

