    public static class StringDelegating {
        private final String value;

        private StringDelegating(String v) { this.value = v; }

        @JsonCreator(mode = JsonCreator.Mode.DELEGATING)
        public static StringDelegating fromString(String str) {
            return new StringDelegating(str);
        }

        public String getValue() { return value; }
    }

    @Test
    public void testDelegatingCreatorWithSimpleType() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        BeanDescription beanDesc = mapper.getSerializationConfig()
                .introspect(mapper.constructType(StringDelegating.class));

        List<BeanPropertyDefinition> properties = beanDesc.findProperties();

        // The delegating parameter "str" should not be a property
        for (BeanPropertyDefinition prop : properties) {
            String name = prop.getName();
            assertFalse("Delegating creator parameter 'str' should not be a property",
                    "str".equals(name));
        }

        // Serialization should have one property (getValue)
        assertEquals("Should have one property in serialization", 1, properties.size());
        assertEquals("Property should be 'value'", "value", properties.get(0).getName());

        // Test deserialization
        StringDelegating result = mapper.readValue("\"test\"", StringDelegating.class);
        assertNotNull(result);
        assertEquals("test", result.getValue());
    }

    // Test for record type to cover uncovered line
    public static class RecordData {
        private final String name;
        private final int age;

        public RecordData(String name, int age) {
            this.name = name;
            this.age = age;
        }

        public String getName() { return name; }
