package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.type.TypeParser;
import org.junit.Test;
import static org.junit.Assert.*;

public class TypeParserGuardrailTest {

    private TypeFactory typeFactory = TypeFactory.defaultInstance();
    private TypeParser parser = new TypeParser(typeFactory);

    @Test
    public void testMaxTypeLengthExceeded() {
        StringBuilder sb = new StringBuilder();
        sb.append("java.util.Map<java.lang.String, java.lang.String>");
        while (sb.length() <= 64000) {
            sb.append("<java.lang.String>");
        }
        String longType = sb.toString();

        try {
            parser.parse(longType);
            fail("Should have thrown IllegalArgumentException for too long type");
        } catch (IllegalArgumentException e) {
            assertTrue("Error message should mention 'too long'", 
                       e.getMessage().contains("too long"));
            assertTrue("Error message should contain length limit", 
                       e.getMessage().contains("64000"));
            assertTrue("Error message should quote input", 
                       e.getMessage().contains("Failed to parse type"));
        }
    }

    @Test
    public void testMaxTypeLengthWithinLimit() {
        String base = "java.util.List<";
        int innerLength = 64000 - base.length() - 1;
        StringBuilder innerBuilder = new StringBuilder();
        for (int i = 0; i < innerLength; i++) {
            innerBuilder.append('a');
        }
        String inner = innerBuilder.toString();
        String atLimitType = base + inner + ">";
        assertEquals("Type string should be exactly 64000 characters", 
                     64000, atLimitType.length());

        try {
            parser.parse(atLimitType);
            fail("Should have failed due to invalid class name");
        } catch (IllegalArgumentException e) {
            assertFalse("Should not fail due to length: " + e.getMessage(), 
                        e.getMessage().contains("too long"));
        }
    }

    @Test
    public void testMaxNestingDepthExceeded() {
        StringBuilder sb = new StringBuilder();
        sb.append("java.util.List");
        for (int i = 0; i < 1000; i++) {
            sb.append("<java.util.List");
        }
        sb.append("<java.util.List<java.lang.String>");
        for (int i = 0; i < 1000; i++) {
            sb.append(">");
        }
        String deeplyNestedType = sb.toString();

        try {
            parser.parse(deeplyNestedType);
            fail("Should have thrown IllegalArgumentException for too deep nesting");
        } catch (IllegalArgumentException e) {
            assertTrue("Error message should mention 'too deeply nested': " + e.getMessage(), 
                       e.getMessage().contains("too deeply nested"));
            assertTrue("Error message should mention nesting limit: " + e.getMessage(), 
                       e.getMessage().contains("1000"));
        }
    }

    @Test
    public void testMaxNestingDepthWithinLimit() {
        StringBuilder sb = new StringBuilder();
        sb.append("java.util.List");
        for (int i = 0; i < 999; i++) {
            sb.append("<java.util.List");
        }
        sb.append("<java.lang.String>");
        for (int i = 0; i < 999; i++) {
            sb.append(">");
        }
        String atLimitNestedType = sb.toString();

        try {
            JavaType type = parser.parse(atLimitNestedType);
            assertNotNull("Should parse type at maximum nesting depth", type);
            assertEquals(java.util.List.class, type.getRawClass());
        } catch (IllegalArgumentException e) {
            fail("Should not throw for valid nesting depth: " + e.getMessage());
        }
    }

    @Test
    public void testNormalTypeParsingStillWorks() {
        String[] testTypes = {
            "java.lang.String",
            "java.util.List<java.lang.String>",
            "java.util.Map<java.lang.String, java.util.List<java.lang.Integer>>",
            "com.fasterxml.jackson.databind.type.TypeParser"
        };

        for (String typeStr : testTypes) {
            try {
                JavaType type = parser.parse(typeStr);
                assertNotNull("Failed to parse: " + typeStr, type);
            } catch (Exception e) {
                fail("Failed to parse valid type: " + typeStr + ", error: " + e.getMessage());
            }
        }
    }

    @Test
    public void testErrorMessagesTruncateLongInput() {
        StringBuilder sb = new StringBuilder();
        sb.append("java.util.Map<");
        for (int i = 0; i < 200; i++) {
            sb.append("java.lang.String,");
        }
        sb.append("java.lang.String>");
        String longType = sb.toString();

        while (longType.length() <= 64000) {
            longType = longType + "<java.lang.String>";
        }

        try {
            parser.parse(longType);
            fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            String msg = e.getMessage();
            assertTrue("Error message should contain truncation indicator: " + msg, 
                       msg.contains("[truncated") || msg.contains("..."));
        }
    }

    @Test
    public void testNestingBudgetDecrementsCorrectly() {
        String typeStr = "java.util.List<java.util.Map<java.lang.String, java.util.Set<java.lang.Integer>>>";

        JavaType type = parser.parse(typeStr);
        assertNotNull(type);
        assertEquals(java.util.List.class, type.getRawClass());
        assertEquals(1, type.containedTypeCount());
        JavaType mapType = type.containedType(0);
        assertEquals(java.util.Map.class, mapType.getRawClass());
    }

    @Test
    public void testEmptyTypeString() {
        try {
            parser.parse("");
            fail("Should have thrown IllegalArgumentException for empty string");
        } catch (IllegalArgumentException e) {
            assertTrue("Error message should mention parsing failure: " + e.getMessage(), 
                       e.getMessage().contains("Failed to parse"));
        }
    }

    @Test
    public void testTypeWithExtraTokens() {
        try {
            parser.parse("java.util.List<java.lang.String> extra");
            fail("Should have thrown IllegalArgumentException for extra tokens");
        } catch (IllegalArgumentException e) {
            assertTrue("Error message should mention unexpected tokens: " + e.getMessage(), 
                       e.getMessage().contains("Unexpected tokens"));
        }
    }

    @Test
    public void testTokenPushBackScenario() {
        String typeStr = "java.util.List>"; 
        try {
            parser.parse(typeStr);
            fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertTrue("Error message should mention parsing issue: " + e.getMessage(),
                       e.getMessage().contains("Unexpected tokens"));
        }
    }
}

