        @com.fasterxml.jackson.annotation.JsonAnySetter
        public EnumMap<TestEnum, String> enumMap;
    }

    // For testing successful initialization of null Map field
    public static class BeanWithNullMapField {
        @com.fasterxml.jackson.annotation.JsonAnySetter
        public Map<String, String> map;
    }

    // For testing unsupported Map type without default constructor
    public static class CustomMap<K, V> extends LinkedHashMap<K, V> {
        public CustomMap(String param) {}
    }

    public static class BeanWithUnsupportedMapField {
        @com.fasterxml.jackson.annotation.JsonAnySetter
        public CustomMap<String, String> customMap;
    }

