    public static class BeanWithAnySetterMethodThatThrows {
        @com.fasterxml.jackson.annotation.JsonAnySetter
        public void handleAny(String key, Object value) {
            throw new RuntimeException("Test exception from any setter");
        }
    }

    // For testing exception during map.put operation
    public static class BeanWithMapThatThrowsOnPut {
        @com.fasterxml.jackson.annotation.JsonAnySetter
        public Map<String, String> map = new HashMap<String, String>() {
            @Override
            public String put(String key, String value) {
                throw new RuntimeException("Test exception from map.put");
            }
        };
    }

    @Test
    public void testAnySetterFieldWithEnumMapAndInvalidKey() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"invalid\":\"value\"}";

        try {
            mapper.readValue(json, BeanWithInitializedEnumMapField.class);
            fail("Should have thrown JsonMappingException");
        } catch (JsonMappingException e) {
            // Verify root cause is InvalidFormatException
            Throwable root = e;
            while (root != null && root.getCause() != null && root.getCause() != root) {
                root = root.getCause();
            }
            assertTrue("Root cause should be InvalidFormatException, found: " + root.getClass(),
                    root instanceof InvalidFormatException);
        }
    }

