            mapper.readValue(json, BeanWithNullEnumMapField.class);
            fail("Should have thrown JsonMappingException");
        } catch (JsonMappingException e) {
            // Get root cause message
            Throwable root = e;
            while (root.getCause() != null && root.getCause() != root) {
                root = root.getCause();
            }
            String msg = root.getMessage();
            assertTrue("Message should contain 'Cannot create an instance of': " + msg,
                    msg.contains("Cannot create an instance of"));
            assertTrue("Message should contain 'EnumMap': " + msg,
                    msg.contains("EnumMap"));
            assertTrue("Message should contain 'any-setter': " + msg,
                    msg.contains("any-setter"));
        }
