        try {
            mapper.readValue(json, BeanWithAnySetterMethodThatThrows.class);
            fail("Should have thrown JsonMappingException");
        } catch (JsonMappingException e) {
            // Verify root cause is our test exception
            Throwable cause = e.getCause();
            assertTrue("Should have RuntimeException as cause", cause instanceof RuntimeException);
            assertEquals("Test exception from any setter", cause.getMessage());
        }
    }

