package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.annotation.JsonSetter;
import com.fasterxml.jackson.annotation.Nulls;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.JsonMappingException;
import org.junit.Test;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;

public class FieldPropertySkipNullsTest {

    public static class Inner {
        public String field1;
    }

    public static class Middle {
        @JsonSetter(nulls = Nulls.SKIP)
        private final List<Inner> list1 = new ArrayList<>();

        public List<Inner> getList1() {
            return list1;
        }
    }

    public static class Outer {
        private List<Middle> list1;

        public List<Middle> getList1() {
            return list1;
        }

        public void setList1(List<Middle> list1) {
            this.list1 = list1;
        }
    }

    public static class MethodPropertyTest {
        private List<String> values = new ArrayList<>();

        @JsonSetter(nulls = Nulls.SKIP)
        public void setValues(List<String> vals) {
            this.values = vals;
        }

        public List<String> getValues() {
            return values;
        }
    }

    public static class TestClass {
        @JsonSetter(nulls = Nulls.SKIP)
        private List<String> list = new ArrayList<>();

        public List<String> getList() {
            return list;
        }
    }

    public static class Nested {
        private String value = "default";

        public String getValue() {
            return value;
        }

        public void setValue(String v) {
            value = v;
        }
    }

    public static class Container {
        @JsonSetter(nulls = Nulls.SKIP)
        private Nested nested = new Nested();

        public Nested getNested() {
            return nested;
        }
    }

    public static class ConstructorTest {
        private final List<String> items;

        @JsonSetter(nulls = Nulls.SKIP)
        public void setItems(List<String> items) {
            if (items != null) {
                this.items.clear();
                this.items.addAll(items);
            }
        }

        public List<String> getItems() {
            return items;
        }

        public ConstructorTest() {
            items = new ArrayList<>();
            items.add("default");
        }
    }

    public static class NonVoidSetterTest {
        private String value = "default";

        @JsonSetter(nulls = Nulls.SKIP)
        public NonVoidSetterTest setValue(String v) {
            this.value = v;
            return this;
        }

        public String getValue() {
            return value;
        }
    }

    public static class FieldPropertyWithCreator {
        private final String name;
        @JsonSetter(nulls = Nulls.SKIP)
        private List<String> values = new ArrayList<>();

        @JsonCreator
        public FieldPropertyWithCreator(@JsonProperty("name") String name) {
            this.name = name;
        }

        public String getName() {
            return name;
        }

        public List<String> getValues() {
            return values;
        }
    }

    public static class SimpleField {
        @JsonSetter(nulls = Nulls.SKIP)
        private List<String> list = new ArrayList<>();

        public List<String> getList() {
            return list;
        }
    }

    public static class IntField {
        @JsonSetter(nulls = Nulls.SKIP)
        private int value;

        public int getValue() {
            return value;
        }
    }

    // New class for testing setAndReturn null-skipping
    public static class SimpleFieldForUpdate {
        @JsonSetter(nulls = Nulls.SKIP)
        public List<String> list = new ArrayList<>();
    }

    // New class for testing setAndReturn exception handling
    public static class IntFieldForUpdate {
        @JsonSetter(nulls = Nulls.SKIP)
        public int value;
    }

    @Test
    public void testSkipNullsWithFieldProperty() throws Exception {
        String json = "{\"list1\":[{\"list1\":null}]}";
        ObjectMapper mapper = new ObjectMapper();
        Outer outer = mapper.readValue(json, Outer.class);

        assertNotNull(outer.getList1());
        assertEquals(1, outer.getList1().size());

        Middle middle = outer.getList1().get(0);
        assertNotNull("list1 should not be null due to @JsonSetter(nulls = SKIP)", middle.getList1());
        assertTrue("list1 should be an empty ArrayList", middle.getList1().isEmpty());
    }

    @Test
    public void testSkipNullsWithMethodProperty() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"values\":null}";
        MethodPropertyTest obj = mapper.readValue(json, MethodPropertyTest.class);

        assertNotNull(obj.getValues());
        assertTrue(obj.getValues().isEmpty());
    }

    @Test
    public void testSkipNullsWithNonNullValue() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"list\":[\"a\",\"b\"]}";
        TestClass obj = mapper.readValue(json, TestClass.class);

        assertNotNull(obj.getList());
        assertEquals(2, obj.getList().size());
        assertEquals("a", obj.getList().get(0));
        assertEquals("b", obj.getList().get(1));
    }

    @Test
