package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;

public class ObjectNodeFindMethodsTest {

    @Test
    public void testFindValues() {
        ObjectMapper mapper = new ObjectMapper();
        // Create a JSON structure with nested "target" fields
        // {
        //   "target": "value1",
        //   "object1": {
        //     "target": "value2",
        //     "nested": {
        //       "target": "value3"
        //     }
        //   },
        //   "object2": {
        //     "target": "value4"
        //   }
        // }
        ObjectNode root = mapper.createObjectNode();
        root.put("target", "value1");

        ObjectNode object1 = mapper.createObjectNode();
        object1.put("target", "value2");
        ObjectNode nested = mapper.createObjectNode();
        nested.put("target", "value3");
        object1.set("nested", nested);
        root.set("object1", object1);

        ObjectNode object2 = mapper.createObjectNode();
        object2.put("target", "value4");
        root.set("object2", object2);

        // Test findValues
        List<JsonNode> values = root.findValues("target");
        assertNotNull(values);
        assertEquals(4, values.size());

        // Verify all four "target" values are found
        List<String> actualValues = new ArrayList<>();
        for (JsonNode node : values) {
            actualValues.add(node.asText());
        }
        assertTrue(actualValues.contains("value1"));
        assertTrue(actualValues.contains("value2"));
        assertTrue(actualValues.contains("value3"));
        assertTrue(actualValues.contains("value4"));
    }

    @Test
    public void testFindValuesAsText() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();
        root.put("target", "value1");

        ObjectNode child = mapper.createObjectNode();
        child.put("target", "value2");
        root.set("child", child);

        ObjectNode sibling = mapper.createObjectNode();
        sibling.put("target", "value3");
        root.set("sibling", sibling);

        // Test findValuesAsText
        List<String> values = root.findValuesAsText("target");
        assertNotNull(values);
        assertEquals(3, values.size());

        assertTrue(values.contains("value1"));
        assertTrue(values.contains("value2"));
        assertTrue(values.contains("value3"));
    }

    @Test
    public void testFindParents() {
        ObjectMapper mapper = new ObjectMapper();
        // Create a JSON structure where "target" appears at multiple levels
        // {
        //   "target": "value1",
        //   "level1": {
        //     "target": "value2",
        //     "level2": {
        //       "target": "value3"
        //     }
        //   }
        // }
        ObjectNode root = mapper.createObjectNode();
        root.put("target", "value1");

        ObjectNode level1 = mapper.createObjectNode();
        level1.put("target", "value2");
        root.set("level1", level1);

        ObjectNode level2 = mapper.createObjectNode();
        level2.put("target", "value3");
        level1.set("level2", level2);

        // Test findParents
        List<JsonNode> parents = root.findParents("target");
        assertNotNull(parents);
        assertEquals(3, parents.size());

        // Verify the parents are correct
        // Parent of first "target" is root
        assertTrue(parents.contains(root));
        // Parent of second "target" is level1
        assertTrue(parents.contains(level1));
        // Parent of third "target" is level2
        assertTrue(parents.contains(level2));
    }

