    @Test
    public void testFindValuesWithArrayChildren() {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();

        ArrayNode array = mapper.createArrayNode();
        ObjectNode arrayElement = mapper.createObjectNode();
        arrayElement.put("target", "arrayValue");
        array.add(arrayElement);
        root.set("array", array);

        root.put("target", "directValue");

        List<JsonNode> values = root.findValues("target");
        assertEquals(2, values.size());

        List<String> texts = new ArrayList<>();
        for (JsonNode node : values) {
            texts.add(node.asText());
        }
        assertTrue(texts.contains("directValue"));
        assertTrue(texts.contains("arrayValue"));
    }

