package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;

public class ObjectNodeFindValuesTest {

    @Test
    public void testFindValuesRecursivelyCollectsAllMatches() throws Exception {
        // Create a JSON structure with nested "target" fields
        // {
        //   "target": "value1",
        //   "object1": {
        //     "target": "value2",
        //     "nested": {
        //       "target": "value3"
        //     }
        //   },
        //   "object2": {
        //     "target": "value4"
        //   }
        // }
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();
        root.put("target", "value1");

        ObjectNode object1 = mapper.createObjectNode();
        object1.put("target", "value2");
        ObjectNode nested = mapper.createObjectNode();
        nested.put("target", "value3");
        object1.set("nested", nested);
        root.set("object1", object1);

        ObjectNode object2 = mapper.createObjectNode();
        object2.put("target", "value4");
        root.set("object2", object2);

        // Test findValues
        List<JsonNode> values = root.findValues("target");
        assertNotNull(values);
        assertEquals(4, values.size());

        // Verify all values are collected in document order
        List<String> actualValues = new ArrayList<>();
        for (JsonNode node : values) {
            actualValues.add(node.asText());
        }
        assertArrayEquals(new String[]{"value1", "value2", "value3", "value4"}, 
                         actualValues.toArray(new String[0]));

        // Test with existing list
        List<JsonNode> existingList = new ArrayList<>();
        List<JsonNode> result = root.findValues("target", existingList);
        assertSame(existingList, result);
        assertEquals(4, existingList.size());
    }

    @Test
    public void testFindValuesAsTextRecursivelyCollectsAllMatches() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();
        root.put("target", "value1");

        ObjectNode child = mapper.createObjectNode();
        child.put("target", "value2");
        root.set("child", child);

        // Test findValuesAsText
        List<String> values = root.findValuesAsText("target");
        assertNotNull(values);
        assertEquals(2, values.size());
        assertArrayEquals(new String[]{"value1", "value2"}, values.toArray(new String[0]));

        // Test with existing list
        List<String> existingList = new ArrayList<>();
        List<String> result = root.findValuesAsText("target", existingList);
        assertSame(existingList, result);
        assertEquals(2, existingList.size());
    }

    @Test
    public void testFindParentsRecursivelyCollectsAllMatches() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();
        root.put("target", "value1");

        ObjectNode object1 = mapper.createObjectNode();
        object1.put("target", "value2");
        root.set("object1", object1);

        ObjectNode object2 = mapper.createObjectNode();
        object2.put("target", "value3");
        root.set("object2", object2);

        // Test findParents
        List<JsonNode> parents = root.findParents("target");
        assertNotNull(parents);
        assertEquals(3, parents.size());

        // All parents should be ObjectNode instances
        for (JsonNode parent : parents) {
            assertTrue(parent instanceof ObjectNode);
        }

        // Verify root appears once, object1 and object2 each appear once
        int rootCount = 0, object1Count = 0, object2Count = 0;
        for (JsonNode parent : parents) {
            if (parent == root) rootCount++;
            else if (parent == object1) object1Count++;
            else if (parent == object2) object2Count++;
        }
        assertEquals(1, rootCount);
        assertEquals(1, object1Count);
        assertEquals(1, object2Count);

        // Test with existing list
        List<JsonNode> existingList = new ArrayList<>();
        List<JsonNode> result = root.findParents("target", existingList);
        assertSame(existingList, result);
        assertEquals(3, existingList.size());
    }

    @Test
    public void testFindValuesDoesNotSearchChildrenOfMatchedParent() throws Exception {
        // When a parent matches, we should not search its children for the same property name
        // This is the "only add children if parent not added" logic
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();

        // Create a structure where a matching parent contains nested matching children
        // These nested children should NOT be included in findValues
        ObjectNode matchedParent = mapper.createObjectNode();
        matchedParent.put("target", "parentValue");
        // Add a child with same property name - this should NOT be searched
        ObjectNode childWithSameName = mapper.createObjectNode();
        childWithSameName.put("target", "childValue");
        matchedParent.set("child", childWithSameName);

        root.set("target", matchedParent); // This is the match

        // Also add a sibling that should be searched
        ObjectNode sibling = mapper.createObjectNode();
        sibling.put("target", "siblingValue");
        root.set("sibling", sibling);

        List<JsonNode> values = root.findValues("target");
        // Should find: matchedParent (value of "target" field) and sibling's "target" value
        // Should NOT find childWithSameName's "target" value
        assertEquals(2, values.size());

        // Verify we got the parent value and sibling value
        boolean foundParent = false, foundSibling = false;
        for (JsonNode node : values) {
            if (node == matchedParent) {
                foundParent = true;
            } else if (node.isTextual() && "siblingValue".equals(node.asText())) {
                foundSibling = true;
            }
            // Ensure nested child value isn't present
            assertNotEquals("childValue", node.asText());
        }
        assertTrue(foundParent);
        assertTrue(foundSibling);
    }

    @Test
    public void testFindValuesWithNullInitialList() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();
        root.put("target", "value1");

        // Test with null initial list
        List<JsonNode> result = root.findValues("target", null);
        assertNotNull(result);
        assertEquals(1, result.size());
        assertEquals("value1", result.get(0).asText());
    }

    @Test
    public void testFindValuesWithEmptyObject() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();

        List<JsonNode> values = root.findValues("target");
        assertNotNull(values);
        assertTrue(values.isEmpty());
    }

    @Test
    public void testFindValuesWithMultipleSiblingMatches() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();

        // Create nested structure with multiple matches
        ObjectNode child1 = mapper.createObjectNode();
        child1.put("target", "value1");
        root.set("child1", child1);

        ObjectNode child2 = mapper.createObjectNode();
        child2.put("target", "value2");
        root.set("child2", child2);

        List<JsonNode> values = root.findValues("target");
        assertEquals(2, values.size());

        List<String> actualValues = new ArrayList<>();
        for (JsonNode node : values) {
            actualValues.add(node.asText());
        }
        assertTrue(actualValues.contains("value1"));
        assertTrue(actualValues.contains("value2"));
    }
}

