        List<String> expected = Arrays.asList("value1", "value2", "value3", "value4", "value5");
        assertTrue("Missing expected values: " + result, 
                   result.containsAll(expected));

        // Test findValuesAsText with existing list
        List<String> existingList = new ArrayList<>();
        existingList.add("existing");
        result = root.findValuesAsText("target", existingList);
        assertEquals(6, result.size());
        expected = Arrays.asList("existing", "value1", "value2", "value3", "value4", "value5");
        assertTrue("Missing expected values: " + result, 
                   result.containsAll(expected));

        // Test with property name that doesn't exist
        result = root.findValuesAsText("nonexistent", null);
        assertNull(result);
    }

    @Test
    public void testFindValuesAsTextShouldNotSearchChildrenOfMatchedParent() throws Exception {
        // When a parent node matches the property name, its children should not be searched
        ObjectMapper mapper = new ObjectMapper();
        String json = "{"
                + "\"target\": {"
                + "  \"nested\": {"
                + "    \"target\": \"shouldNotBeFound\""
                + "  }"
                + "},"
                + "\"other\": {"
                + "  \"target\": \"shouldBeFound\""
                + "}"
                + "}";

        JsonNode root = mapper.readTree(json);

        List<String> result = root.findValuesAsText("target", null);
        // Should find 2 values: 
        //   1. The object at root level (asText() returns empty string)
        //   2. "shouldBeFound" from the 'other' branch
        assertEquals(2, result.size());
        assertTrue("Should contain empty string from object node", 
                   result.contains(""));
        assertTrue("Should contain 'shouldBeFound'", 
                   result.contains("shouldBeFound"));
    }

    @Test
    public void testFindValuesShouldCollectAllMatchesRecursively() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{"
                + "\"target\": \"value1\","
                + "\"nested\": {"
                + "  \"target\": \"value2\""
                + "}"
                + "}";

        JsonNode root = mapper.readTree(json);

        List<JsonNode> result = root.findValues("target", null);
        assertNotNull(result);
        assertEquals(2, result.size());

        // Both should be TextNode instances
        for (JsonNode node : result) {
            assertTrue(node.isTextual());
        }
    }

    @Test
    public void testFindParentsShouldCollectAllParentNodes() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{"
                + "\"target\": \"value1\","
                + "\"nested\": {"
                + "  \"target\": \"value2\""
                + "}"
                + "}";

        JsonNode root = mapper.readTree(json);

        List<JsonNode> result = root.findParents("target", null);
        assertNotNull(result);
        assertEquals(2, result.size());

        // First parent should be the root object
        assertEquals(root, result.get(0));
        // Second parent should be the nested object
        assertTrue(result.get(1).isObject());
        assertEquals(1, result.get(1).size());
    }

    @Test
    public void testFindValuesAsTextWithEmptyObject() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{}";
        JsonNode root = mapper.readTree(json);

        List<String> result = root.findValuesAsText("any", null);
        assertNull(result);
    }

    @Test
    public void testFindValuesAsTextWithMultipleSiblingMatches() throws Exception {
        // Test case where multiple direct children match
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode root = mapper.createObjectNode();
        root.put("target", "value1");
        root.put("other", "ignored");
        root.put("another", "value3");

        // Add a nested object with target
