package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.ObjectWriter;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.core.SerializableString;
import com.fasterxml.jackson.databind.cfg.EnumFeature;
import com.fasterxml.jackson.databind.SerializationFeature;
import org.junit.Test;
import static org.junit.Assert.*;

public class EnumValuesTest {

    // Test enum with a constant that returns null from toString()
    public enum NullToStringEnum {
        ALPHA {
            @Override
            public String toString() {
                return "ALPHA";
            }
        },
        BETA {
            @Override
            public String toString() {
                return "BETA";
            }
        },
        GAMMA {
            @Override
            public String toString() {
                return null; // This triggers the issue
            }
        }
    }

    // Test enum with all non-null toString() for baseline
    public enum NormalEnum {
        FOO, BAR
    }

    // Edge case: enum where all toString() return null
    public enum AllNullToStringEnum {
        VALUE1 {
            @Override
            public String toString() {
                return null;
            }
        },
        VALUE2 {
            @Override
            public String toString() {
                return null;
            }
        }
    }

    @Test
    public void testConstructFromToStringWithNullToString() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        MapperConfig<?> config = mapper.getSerializationConfig();
        AnnotatedClass annotatedClass = AnnotatedClass.constructWithoutSuperTypes(
                NullToStringEnum.class, config);

        // This should not throw IllegalStateException after the fix
        EnumValues enumValues = EnumValues.constructFromToString(config, annotatedClass);

        // Verify that the null toString() was coerced to empty string
        assertEquals("ALPHA", enumValues.serializedValueFor(NullToStringEnum.ALPHA).getValue());
        assertEquals("BETA", enumValues.serializedValueFor(NullToStringEnum.BETA).getValue());
        assertEquals("", enumValues.serializedValueFor(NullToStringEnum.GAMMA).getValue()); // null -> empty string
    }

    @Test
    public void testObjectWriterCreationWithNullToStringEnum() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Must enable using toString() for enum serialization
        mapper.enable(SerializationFeature.WRITE_ENUMS_USING_TO_STRING);

        // This should not throw any exception after the fix
        ObjectWriter writer = mapper.writerFor(NullToStringEnum.class);

        // Verify serialization works
        assertEquals("\"ALPHA\"", writer.writeValueAsString(NullToStringEnum.ALPHA));
        assertEquals("\"BETA\"", writer.writeValueAsString(NullToStringEnum.BETA));
        assertEquals("\"\"", writer.writeValueAsString(NullToStringEnum.GAMMA)); // null -> empty string
    }

    @Test
    public void testConstructFromToStringWithLowerCase() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Use MapperConfig to enable EnumFeature instead of ObjectMapper.enable()
        MapperConfig<?> config = mapper.getSerializationConfig()
                .with(EnumFeature.WRITE_ENUMS_TO_LOWERCASE);
        AnnotatedClass annotatedClass = AnnotatedClass.constructWithoutSuperTypes(
                NullToStringEnum.class, config);

        EnumValues enumValues = EnumValues.constructFromToString(config, annotatedClass);

        // Verify lowercasing and null handling
        assertEquals("alpha", enumValues.serializedValueFor(NullToStringEnum.ALPHA).getValue());
        assertEquals("beta", enumValues.serializedValueFor(NullToStringEnum.BETA).getValue());
        assertEquals("", enumValues.serializedValueFor(NullToStringEnum.GAMMA).getValue()); // null -> empty string, then lowercased (still empty)
    }

    @Test
    public void testConstructFromToStringWithNormalEnum() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        MapperConfig<?> config = mapper.getSerializationConfig();
        AnnotatedClass annotatedClass = AnnotatedClass.constructWithoutSuperTypes(
                NormalEnum.class, config);

        EnumValues enumValues = EnumValues.constructFromToString(config, annotatedClass);

        assertEquals("FOO", enumValues.serializedValueFor(NormalEnum.FOO).getValue());
        assertEquals("BAR", enumValues.serializedValueFor(NormalEnum.BAR).getValue());
    }

    @Test
    public void testConstructFromToStringWithAllNullToString() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        MapperConfig<?> config = mapper.getSerializationConfig();
        AnnotatedClass annotatedClass = AnnotatedClass.constructWithoutSuperTypes(
                AllNullToStringEnum.class, config);

        // This should not throw after the fix
