import com.fasterxml.jackson.core.SerializableString;
import com.fasterxml.jackson.databind.cfg.EnumFeature;
import com.fasterxml.jackson.databind.SerializationFeature;
import org.junit.Test;
import static org.junit.Assert.*;

public class EnumValuesTest {

    // Test enum with a constant that returns null from toString()
    public enum NullToStringEnum {
        ALPHA {
            @Override
            public String toString() {
                return "ALPHA";
            }
        },
        BETA {
            @Override
            public String toString() {
                return "BETA";
            }
        },
        GAMMA {
            @Override
            public String toString() {
                return null; // This triggers the issue
            }
        }
    }

    // Test enum with all non-null toString() for baseline
    public enum NormalEnum {
        FOO, BAR
    }

    // Edge case: enum where all toString() return null
    public enum AllNullToStringEnum {
        VALUE1 {
            @Override
            public String toString() {
                return null;
            }
        },
        VALUE2 {
            @Override
            public String toString() {
                return null;
            }
        }
    }

    @Test
    public void testConstructFromToStringWithNullToString() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        MapperConfig<?> config = mapper.getSerializationConfig();
        AnnotatedClass annotatedClass = AnnotatedClass.constructWithoutSuperTypes(
                NullToStringEnum.class, config);

        // This should not throw IllegalStateException after the fix
        EnumValues enumValues = EnumValues.constructFromToString(config, annotatedClass);

        // Verify that the null toString() was coerced to empty string
        assertEquals("ALPHA", enumValues.serializedValueFor(NullToStringEnum.ALPHA).getValue());
        assertEquals("BETA", enumValues.serializedValueFor(NullToStringEnum.BETA).getValue());
        assertEquals("", enumValues.serializedValueFor(NullToStringEnum.GAMMA).getValue()); // null -> empty string
    }

