    public static class TestBeanWithFeature {
        @JsonFormat(with = JsonFormat.Feature.READ_UNKNOWN_ENUM_VALUES_AS_NULL)
        public Color color;
    }

    @Test
    public void testUseNullForUnknownEnumWithAnnotationOverride() throws Exception {
        // Setup ObjectMapper with global feature enabled
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);

        // Test with annotated field - should throw exception
        String jsonWithUnknown = "{\"color\":\"WHITE\"}";

        try {
            mapper.readValue(jsonWithUnknown, TestBean.class);
            fail("Expected InvalidFormatException when unknown enum value is encountered with @JsonFormat(without = READ_UNKNOWN_ENUM_VALUES_AS_NULL)");
        } catch (InvalidFormatException e) {
            // Expected - annotation should override global setting
            assertTrue(e.getMessage().contains("WHITE"));
            assertTrue(e.getMessage().contains("not one of the values accepted"));
        }

        // Test with plain field - should return null due to global setting
        PlainBean plainBean = mapper.readValue(jsonWithUnknown, PlainBean.class);
        assertNull("Plain field should return null when global feature is enabled", plainBean.color);
    }

    @Test
    public void testUseNullForUnknownEnumWithoutGlobalFeature() throws Exception {
        // Setup ObjectMapper without global feature
        ObjectMapper mapper = new ObjectMapper();
        mapper.disable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);

