import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import static org.junit.Assert.*;

public class BeanDeserializerBaseExternalTypeHandlerTest {

    @JsonIgnoreProperties(ignoreUnknown = true)
    public static class Parent {
        public Child child;
    }

    public static class Child {
        public String childType;

        @JsonTypeInfo(use = JsonTypeInfo.Id.NAME, include = JsonTypeInfo.As.EXTERNAL_PROPERTY, property = "childType")
        @JsonSubTypes({
            @JsonSubTypes.Type(value = SubChildA.class, name = "A"),
            @JsonSubTypes.Type(value = SubChildB.class, name = "B")
        })
        public Object subChild;
    }

    public static class SubChildA {
        public String aField;
    }

    public static class SubChildB {
        public String bField;
    }

    @Test
    public void testExternalTypeHandlerPreservedWithJsonIgnoreProperties() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();

        // JSON that matches the structure with external type property
        String json = "{\"child\":{\"childType\":\"A\", \"subChild\": {\"aField\":\"test\"} }}";

        Parent parent = mapper.readValue(json, Parent.class);

        assertNotNull(parent);
        assertNotNull(parent.child);
        assertEquals("A", parent.child.childType);
        assertNotNull(parent.child.subChild);
        assertTrue(parent.child.subChild instanceof SubChildA);
        assertEquals("test", ((SubChildA) parent.child.subChild).aField);
    }

    @Test
    public void testExternalTypeHandlerWithDifferentSubTypes() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();

        // Test with type B
        String json = "{\"child\":{\"childType\":\"B\", \"subChild\": {\"bField\":\"testB\"} }}";

        Parent parent = mapper.readValue(json, Parent.class);

        assertNotNull(parent);
        assertNotNull(parent.child);
        assertEquals("B", parent.child.childType);
        assertNotNull(parent.child.subChild);
        assertTrue(parent.child.subChild instanceof SubChildB);
        assertEquals("testB", ((SubChildB) parent.child.subChild).bField);
    }

    @Test
    public void testExternalTypeHandlerWithMissingExternalProperty() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();

        // JSON without the external type property - should fail
        String json = "{\"child\":{\"subChild\": {\"aField\":\"test\"} }}";

        try {
            mapper.readValue(json, Parent.class);
            fail("Should have thrown exception due to missing external type property");
        } catch (JsonProcessingException e) {
            // Expected - missing external type property
            // Check for either the expected message or the property name in the exception
            String msg = e.getMessage();
            assertTrue("Exception message should indicate missing type information: " + msg,
                    msg.contains("Missing type id") || msg.contains("childType"));
        }
    }

    @Test
    public void testExternalTypeHandlerWithUnknownPropertiesIgnored() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();

        // JSON with extra properties at parent level (should be ignored)
        String json = "{\"extraParent\":\"ignore\", \"child\":{\"childType\":\"A\", \"subChild\": {\"aField\":\"test\"} }}";

        Parent parent = mapper.readValue(json, Parent.class);

        assertNotNull(parent);
        assertNotNull(parent.child);
        assertEquals("A", parent.child.childType);
        assertNotNull(parent.child.subChild);
        assertTrue(parent.child.subChild instanceof SubChildA);
        assertEquals("test", ((SubChildA) parent.child.subChild).aField);
    }

    @JsonIgnoreProperties({"ignoredField"})
    public static class ParentWithSpecificIgnore {
        public Child child;
    }

    @Test
    public void testExternalTypeHandlerWithSpecificIgnoredProperties() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();

        // JSON with specifically ignored property at parent level
        String json = "{\"ignoredField\":\"shouldBeIgnored\", \"child\":{\"childType\":\"A\", \"subChild\": {\"aField\":\"test\"} }}";

        ParentWithSpecificIgnore parent = mapper.readValue(json, ParentWithSpecificIgnore.class);

        assertNotNull(parent);
        assertNotNull(parent.child);
        assertEquals("A", parent.child.childType);
        assertNotNull(parent.child.subChild);
        assertTrue(parent.child.subChild instanceof SubChildA);
        assertEquals("test", ((SubChildA) parent.child.subChild).aField);
    }

    // New test case to cover unwrapped deserialization
    public static class ParentUnwrapped {
        @JsonUnwrapped
        public Child child;
    }

    @Test
    public void testExternalTypeHandlerWithUnwrapped() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();

        // JSON with unwrapped child properties
        String json = "{\"childType\":\"A\", \"subChild\": {\"aField\":\"test\"} }";

        ParentUnwrapped parent = mapper.readValue(json, ParentUnwrapped.class);

        assertNotNull(parent);
        assertNotNull(parent.child);
        assertEquals("A", parent.child.childType);
        assertNotNull(parent.child.subChild);
        assertTrue(parent.child.subChild instanceof SubChildA);
        assertEquals("test", ((SubChildA) parent.child.subChild).aField);
    }

    // New test case to cover ObjectIdReader constructor path
    @JsonIdentityInfo(generator = ObjectIdGenerators.PropertyGenerator.class, property = "id")
    public static class ObjectIdParent {
        public int id;
        public Child child;
    }

    @Test
    public void testExternalTypeHandlerWithObjectId() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();

        // JSON with object id and external type property
        String json = "{\"id\":1, \"child\":{\"childType\":\"A\", \"subChild\": {\"aField\":\"test\"} }}";

        ObjectIdParent parent = mapper.readValue(json, ObjectIdParent.class);

        assertNotNull(parent);
        assertEquals(1, parent.id);
        assertNotNull(parent.child);
        assertEquals("A", parent.child.childType);
        assertNotNull(parent.child.subChild);
        assertTrue(parent.child.subChild instanceof SubChildA);
        assertEquals("test", ((SubChildA) parent.child.subChild).aField);
    }
}

