import org.junit.Test;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;

public class MethodPropertySkipNullsTest {

    public static class Inner {
        public String field1;
    }

    public static class Middle {
        @JsonSetter(nulls = Nulls.SKIP)
        private List<Inner> list1 = new ArrayList<>();

        public List<Inner> getList1() {
            return list1;
        }

        public void setList1(List<Inner> list1) {
            this.list1 = list1;
        }
    }

    public static class Outer {
        private List<Middle> list1;

        public List<Middle> getList1() {
            return list1;
        }

        public void setList1(List<Middle> list1) {
            this.list1 = list1;
        }
    }

    @Test
    public void testSkipNullsWithNestedObject() throws Exception {
        String json = "{\"list1\":[{\"list1\":null}]}";
        ObjectMapper mapper = new ObjectMapper();
        Outer outer = mapper.readValue(json, Outer.class);

        assertNotNull(outer);
        assertNotNull(outer.getList1());
        assertEquals(1, outer.getList1().size());

        Middle middle = outer.getList1().get(0);
        assertNotNull("list1 should not be null due to skip nulls", middle.getList1());
        assertTrue(middle.getList1().isEmpty());
    }

    @Test
    public void testSkipNullsWithDirectSetter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"list1\":null}";
        Middle middle = mapper.readValue(json, Middle.class);

        assertNotNull(middle);
        assertNotNull(middle.getList1());
        assertTrue(middle.getList1().isEmpty());
    }

    @Test
    public void testSkipNullsWithNonNullValue() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"list1\":[{\"field1\":\"value1\"}]}";
        Middle middle = mapper.readValue(json, Middle.class);

        assertNotNull(middle);
        assertNotNull(middle.getList1());
        assertEquals(1, middle.getList1().size());
        assertEquals("value1", middle.getList1().get(0).field1);
    }

    public static class MixedProperty {
        private final List<String> items = new ArrayList<>();

        @JsonSetter(nulls = Nulls.SKIP)
        public void setItems(List<String> items) {
            this.items.clear();
            if (items != null) {
                this.items.addAll(items);
            }
        }

        public List<String> getItems() {
            return items;
        }
    }

    @Test
    public void testSkipNullsWithMixedProperty() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"items\":null}";
        MixedProperty obj = mapper.readValue(json, MixedProperty.class);

        assertNotNull(obj);
        assertNotNull(obj.getItems());
        assertTrue(obj.getItems().isEmpty());
    }

    public static class NoSkipProperty {
        private List<String> items;

        public List<String> getItems() {
            return items;
        }

        public void setItems(List<String> items) {
            this.items = items;
        }
    }

