    public void testWithoutSkipNulls() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"items\":null}";
        NoSkipProperty obj = mapper.readValue(json, NoSkipProperty.class);

        assertNotNull(obj);
        assertNull(obj.getItems());
    }

    // Test for field-based null skipping
    public static class FieldSkipNulls {
        @JsonSetter(nulls = Nulls.SKIP)
        public List<String> items = new ArrayList<>();
    }

