    public void testSkipNullsWithField() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"items\":null}";
        FieldSkipNulls obj = mapper.readValue(json, FieldSkipNulls.class);

        assertNotNull(obj);
        assertNotNull(obj.items);
        assertTrue(obj.items.isEmpty());
    }

    // Test exception handling in setter (void return)
    public static class SetterWithException {
        private int value;

        @JsonSetter(nulls = Nulls.SKIP)
        public void setValue(String str) {
            value = Integer.parseInt(str);
        }
    }

    @Test(expected = IOException.class)
    public void testSetterWithException() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"value\":\"abc\"}";
        mapper.readValue(json, SetterWithException.class);
    }

    // Test setter with return value handling
    public static class SetterWithReturn {
        private int value;

        @JsonSetter(nulls = Nulls.SKIP)
        public SetterWithReturn setValue(int v) {
            value = v;
            return this;
        }
    }

    @Test
    public void testSetterWithReturn() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"value\":123}";
        SetterWithReturn obj = mapper.readValue(json, SetterWithReturn.class);
        assertNotNull(obj);
        assertEquals(123, obj.value);
    }

    // Test exception handling in setter with return value
    @Test(expected = IOException.class)
    public void testSetterWithReturnException() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"value\":\"abc\"}";
        mapper.readValue(json, SetterWithReturn.class);
    }

    // New test to cover early return in MethodProperty.set()
    public static class SetterWithSkipNulls {
        private List<String> items = new ArrayList<>();
        private boolean setterCalled = false;

        @JsonSetter(nulls = Nulls.SKIP)
        public void setItems(List<String> items) {
            setterCalled = true;
            this.items = items;
        }

        public List<String> getItems() {
            return items;
        }

        public boolean isSetterCalled() {
            return setterCalled;
        }
    }

    @Test
    public void testSkipNullsWithSetter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Test with non-null value
        String json1 = "{\"items\":[\"a\"]}";
        SetterWithSkipNulls obj1 = mapper.readValue(json1, SetterWithSkipNulls.class);
        assertNotNull(obj1);
        assertNotNull(obj1.getItems());
        assertEquals(1, obj1.getItems().size());
        assertTrue(obj1.isSetterCalled());

        // Test with null value: setter should not be called
        String json2 = "{\"items\":null}";
        SetterWithSkipNulls obj2 = mapper.readValue(json2, SetterWithSkipNulls.class);
        assertNotNull(obj2);
        assertNotNull(obj2.getItems()); // remains the initial empty list
        assertTrue(obj2.getItems().isEmpty());
        assertFalse(obj2.isSetterCalled()); // setter not called
    }

    // New test to cover setAndReturn in MethodProperty
    public static class SetterWithReturnSkip {
        private int value;
        private boolean called = false;

        @JsonSetter(nulls = Nulls.SKIP)
        public SetterWithReturnSkip setValue(Integer v) {
            called = true;
            if (v != null) {
                value = v;
            }
            return this;
        }
    }

    @Test
    public void testSkipNullsWithSetterReturn() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Test non-null
        String json1 = "{\"value\":123}";
        SetterWithReturnSkip obj1 = mapper.readValue(json1, SetterWithReturnSkip.class);
        assertNotNull(obj1);
        assertEquals(123, obj1.value);
        assertTrue(obj1.called);

        // Test null: should skip, so setter not called
        String json2 = "{\"value\":null}";
        SetterWithReturnSkip obj2 = mapper.readValue(json2, SetterWithReturnSkip.class);
        assertNotNull(obj2);
        assertEquals(0, obj2.value); // remains 0
        assertFalse(obj2.called);
    }
}

