package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.databind.introspect.AnnotationIntrospectorPair;
import com.fasterxml.jackson.databind.introspect.JacksonAnnotationIntrospector;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.databind.introspect.Annotated;
import com.fasterxml.jackson.databind.introspect.AnnotatedField;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.annotation.JsonRootName;
import com.fasterxml.jackson.annotation.JsonSetter;
import com.fasterxml.jackson.annotation.JsonAnySetter;
import org.junit.Test;
import static org.junit.Assert.*;

public class PropertyNameMergeTest {

    static class DummyClass { }

    // Test the private helper _nonEmpty via the public merge method
    @Test
    public void testMergeSimpleNames() {
        // Both null -> null
        assertNull(PropertyName.merge(null, null));

        // First null, second non-null -> second
        PropertyName pn2 = new PropertyName("simple2");
        assertEquals(pn2, PropertyName.merge(null, pn2));

        // First non-null, second null -> first
        PropertyName pn1 = new PropertyName("simple1");
        assertEquals(pn1, PropertyName.merge(pn1, null));

        // First has non-empty simple name, second has different -> use first
        PropertyName merged = PropertyName.merge(pn1, pn2);
        assertEquals("simple1", merged.getSimpleName());
        assertNull(merged.getNamespace());

        // First has empty simple name, second has non-empty -> use second
        PropertyName empty = new PropertyName("");
        merged = PropertyName.merge(empty, pn2);
        assertEquals("simple2", merged.getSimpleName());

        // First has null simple name (impossible in practice but test via constructor)
        // Actually PropertyName constructor doesn't allow null simpleName, so skip

        // Return same instance when possible
        PropertyName same = PropertyName.merge(pn1, pn1);
        assertSame(pn1, same);

        // When first has empty simple name and second has empty -> empty
        PropertyName empty2 = new PropertyName("");
        merged = PropertyName.merge(empty, empty2);
        assertEquals("", merged.getSimpleName());
    }

    @Test
    public void testMergeWithNamespaces() {
        // First has namespace, second doesn't -> use first's namespace
        PropertyName ns1 = new PropertyName("simple", "ns1");
        PropertyName noNs = new PropertyName("simple");
        PropertyName merged = PropertyName.merge(ns1, noNs);
        assertEquals("simple", merged.getSimpleName());
        assertEquals("ns1", merged.getNamespace());

        // First has no namespace, second has -> use second's namespace
        merged = PropertyName.merge(noNs, ns1);
        assertEquals("simple", merged.getSimpleName());
        assertEquals("ns1", merged.getNamespace());

        // First has empty namespace string, second has non-empty -> use second's
        PropertyName emptyNs = new PropertyName("simple", "");
        merged = PropertyName.merge(emptyNs, ns1);
        assertEquals("simple", merged.getSimpleName());
        assertEquals("ns1", merged.getNamespace());

        // First has non-empty namespace, second has different -> use first's
        PropertyName ns2 = new PropertyName("simple", "ns2");
        merged = PropertyName.merge(ns1, ns2);
        assertEquals("simple", merged.getSimpleName());
        assertEquals("ns1", merged.getNamespace());

        // Both have same namespace -> return first instance
        PropertyName ns1b = new PropertyName("simple", "ns1");
        merged = PropertyName.merge(ns1, ns1b);
        // Should return ns1 since all fields match
        assertSame(ns1, merged);
    }

    @Test
    public void testMergeWithNullNamespace() {
        PropertyName nullNs = new PropertyName("name", null);
        PropertyName withNs = new PropertyName("name", "ns");

        // Merge nullNs (first) and withNs (second): 
        // namespace: nullNs._namespace is null -> returns withNs._namespace
        // simple: same -> "name"
        // Then check: matches withNs -> return withNs.
        PropertyName merged = PropertyName.merge(nullNs, withNs);
        assertSame(withNs, merged);

        // Reverse: withNs first, nullNs second
        merged = PropertyName.merge(withNs, nullNs);
        // namespace: withNs._namespace is non-null and non-empty -> "ns"
        // simple: same -> "name"
        // matches withNs -> return withNs.
        assertSame(withNs, merged);
    }

    @Test
    public void testMergeWithEmptyNamespace() {
        PropertyName emptyNs = new PropertyName("name", "");
        PropertyName withNs = new PropertyName("name", "ns");

        // Merge emptyNs (first) and withNs (second): 
        // namespace: emptyNs._namespace is empty -> returns withNs._namespace
        // simple: same -> "name"
        // Then check: matches withNs -> return withNs.
        PropertyName merged = PropertyName.merge(emptyNs, withNs);
        assertSame(withNs, merged);

        // Reverse: withNs first, emptyNs second
        merged = PropertyName.merge(withNs, emptyNs);
        // namespace: withNs._namespace is non-empty -> "ns" -> matches withNs -> return withNs.
        assertSame(withNs, merged);
    }

    @Test
    public void testMergeWithUseDefault() {
        // USE_DEFAULT has empty simple name and null namespace
        PropertyName custom = new PropertyName("custom");
        PropertyName merged = PropertyName.merge(PropertyName.USE_DEFAULT, custom);
        // USE_DEFAULT has empty simple name, so should use custom's simple name
        assertEquals("custom", merged.getSimpleName());
        assertNull(merged.getNamespace());

        // Reverse: custom first, USE_DEFAULT second -> use custom
        merged = PropertyName.merge(custom, PropertyName.USE_DEFAULT);
        assertEquals("custom", merged.getSimpleName());
        assertNull(merged.getNamespace());

        // Both USE_DEFAULT -> USE_DEFAULT
        merged = PropertyName.merge(PropertyName.USE_DEFAULT, PropertyName.USE_DEFAULT);
        assertSame(PropertyName.USE_DEFAULT, merged);
    }

    // Test AnnotationIntrospectorPair integration
    static class TestIntrospector extends com.fasterxml.jackson.databind.AnnotationIntrospector {
        private final PropertyName serializationName;
        private final PropertyName deserializationName;
        private final PropertyName wrapperName;
        private final PropertyName rootName;
        private final PropertyName renameByField;

        TestIntrospector(PropertyName serializationName, PropertyName deserializationName,
                         PropertyName wrapperName, PropertyName rootName, PropertyName renameByField) {
            this.serializationName = serializationName;
            this.deserializationName = deserializationName;
            this.wrapperName = wrapperName;
            this.rootName = rootName;
            this.renameByField = renameByField;
        }

        @Override
        public PropertyName findNameForSerialization(Annotated a) {
            return serializationName;
        }

        @Override
        public PropertyName findNameForDeserialization(Annotated a) {
            return deserializationName;
        }

        @Override
        public PropertyName findWrapperName(Annotated a) {
            return wrapperName;
        }

        @Override
        public PropertyName findRootName(AnnotatedClass ac) {
            return rootName;
        }

        @Override
        public PropertyName findRenameByField(MapperConfig<?> config, AnnotatedField f, PropertyName implName) {
            return renameByField;
        }

        // Other methods with default implementations
        @Override
        public com.fasterxml.jackson.core.Version version() {
            return com.fasterxml.jackson.core.Version.unknownVersion();
        }
    }

    @Test
    public void testAnnotationIntrospectorPairMerge() throws Exception {
        // Primary has empty simple name, secondary has explicit -> should use secondary
        PropertyName primaryName = new PropertyName("", "primaryNs");
        PropertyName secondaryName = new PropertyName("explicit", "secondaryNs");

        TestIntrospector primary = new TestIntrospector(primaryName, primaryName, primaryName, primaryName, primaryName);
        TestIntrospector secondary = new TestIntrospector(secondaryName, secondaryName, secondaryName, secondaryName, secondaryName);

        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(primary, secondary);

        // Use properly initialized AnnotatedClass
        ObjectMapper mapper = new ObjectMapper();
        BeanDescription beanDesc = mapper.getSerializationConfig()
                .introspectClassAnnotations(DummyClass.class);
        AnnotatedClass annotated = beanDesc.getClassInfo();

        // Test findNameForSerialization
        PropertyName result = pair.findNameForSerialization(annotated);
        assertEquals("explicit", result.getSimpleName());
        assertEquals("primaryNs", result.getNamespace()); // primary namespace is non-empty

        // Test findNameForDeserialization
        result = pair.findNameForDeserialization(annotated);
        assertEquals("explicit", result.getSimpleName());
        assertEquals("primaryNs", result.getNamespace());

        // Test findWrapperName
        result = pair.findWrapperName(annotated);
        assertEquals("explicit", result.getSimpleName());
        assertEquals("primaryNs", result.getNamespace());

        // Test findRootName
        result = pair.findRootName(annotated);
        assertEquals("explicit", result.getSimpleName());
        assertEquals("primaryNs", result.getNamespace());

        // Test findRenameByField - note order is swapped: secondary first
        result = pair.findRenameByField(null, null, null);
        assertEquals("explicit", result.getSimpleName());
        assertEquals("secondaryNs", result.getNamespace()); // secondary first, so its namespace used
    }

    @Test
    public void testMergeWithJsonPropertyAndJacksonXmlProperty() throws Exception {
        // Simulate the scenario from the requirement:
        // @JacksonXmlProperty(isAttribute=true) - defaults: empty local name, empty namespace
        // @JsonProperty(namespace="uri:ns1", value="prop")

        PropertyName jacksonXmlName = new PropertyName("", ""); // defaults
        PropertyName jsonPropName = new PropertyName("prop", "uri:ns1");

        // Primary introspector (JacksonXml) returns empty names
        // Secondary introspector (JacksonAnnotation) returns explicit values
        TestIntrospector xmlIntrospector = new TestIntrospector(
            jacksonXmlName, jacksonXmlName, jacksonXmlName, jacksonXmlName, jacksonXmlName);
        TestIntrospector jsonIntrospector = new TestIntrospector(
            jsonPropName, jsonPropName, jsonPropName, jsonPropName, jsonPropName);

        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(xmlIntrospector, jsonIntrospector);

        // Use properly initialized AnnotatedClass
        ObjectMapper mapper = new ObjectMapper();
        BeanDescription beanDesc = mapper.getSerializationConfig()
                .introspectClassAnnotations(DummyClass.class);
        AnnotatedClass annotated = beanDesc.getClassInfo();

        PropertyName result = pair.findNameForSerialization(annotated);
        assertEquals("prop", result.getSimpleName());
        assertEquals("uri:ns1", result.getNamespace());

        result = pair.findNameForDeserialization(annotated);
        assertEquals("prop", result.getSimpleName());
        assertEquals("uri:ns1", result.getNamespace());
    }

    @Test
    public void testMergeReturnsSameInstanceWhenPossible() {
        // Case 1: merged result is same as name1 -> return name1
        PropertyName name1 = new PropertyName("same", "ns");
        PropertyName name2 = new PropertyName("same", "ns");
        // Even though name2 has same content, we return name1 because the merged values match name1
        PropertyName merged = PropertyName.merge(name1, name2);
        assertSame(name1, merged);

        // Case 2: merged result is same as name2 -> return name2
        // How? If name1 has empty or null for both, then we use name2.
        PropertyName empty = new PropertyName("", "");
        PropertyName name3 = new PropertyName("non-empty", "ns");
        merged = PropertyName.merge(empty, name3);
        // The merged simple name is "non-empty", namespace is "ns" -> matches name3
        assertSame(name3, merged);

        // Case 3: merged result doesn't match either -> new instance
        PropertyName name4 = new PropertyName("combined", "");
        PropertyName name5 = new PropertyName("", "ns-combined");
        merged = PropertyName.merge(name4, name5);
        // For simple name: name4 has non-empty -> "combined"
        // For namespace: name4 has empty -> so we take name5's namespace -> "ns-combined"
        // Now, does this match name4? name4 has simple="combined", namespace="" -> no.
        // Does it match name5? name5 has simple="", namespace="ns-combined" -> no.
        // So we create a new instance.
        assertNotSame(name4, merged);
        assertNotSame(name5, merged);
        assertEquals("combined", merged.getSimpleName());
        assertEquals("ns-combined", merged.getNamespace());
    }

    @Test
    public void testHashCodeConsistency() {
        PropertyName p1 = new PropertyName("test", "ns");
        PropertyName p2 = new PropertyName("test", "ns");

        // Equal objects must have equal hash codes
        assertEquals(p1.hashCode(), p2.hashCode());

        // Different namespace -> different hash code
        PropertyName p3 = new PropertyName("test", "other");
        assertNotEquals(p1.hashCode(), p3.hashCode());

        // Different simple name -> different hash code
        PropertyName p4 = new PropertyName("other", "ns");
        assertNotEquals(p1.hashCode(), p4.hashCode());
    }

    @Test
    public void testFindRenameByFieldOrder() {
        // Primary returns non-null, secondary returns non-null -> secondary should be used (higher precedence)
        PropertyName primaryName = new PropertyName("primary", "ns1");
        PropertyName secondaryName = new PropertyName("secondary", "ns2");

        TestIntrospector primary = new TestIntrospector(null, null, null, null, primaryName);
        TestIntrospector secondary = new TestIntrospector(null, null, null, null, secondaryName);

        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(primary, secondary);

        PropertyName result = pair.findRenameByField(null, null, null);
        // Secondary is first argument (higher precedence), so its value should be used
        assertEquals("secondary", result.getSimpleName());
        assertEquals("ns2", result.getNamespace());
    }
}

