        PropertyName primaryName = new PropertyName("", "primaryNs");
        PropertyName secondaryName = new PropertyName("explicit", "secondaryNs");

        TestIntrospector primary = new TestIntrospector(primaryName, primaryName, primaryName, primaryName, primaryName);
        TestIntrospector secondary = new TestIntrospector(secondaryName, secondaryName, secondaryName, secondaryName, secondaryName);

        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(primary, secondary);

