        // Secondary introspector (JacksonAnnotation) returns explicit values
        TestIntrospector xmlIntrospector = new TestIntrospector(
            jacksonXmlName, jacksonXmlName, jacksonXmlName, jacksonXmlName, jacksonXmlName);
        TestIntrospector jsonIntrospector = new TestIntrospector(
            jsonPropName, jsonPropName, jsonPropName, jsonPropName, jsonPropName);

