    @Test
    public void testMergeReturnsSameInstanceWhenPossible() {
        // Case 1: merged result is same as name1 -> return name1
        PropertyName name1 = new PropertyName("same", "ns");
        PropertyName name2 = new PropertyName("same", "ns");
        // Even though name2 has same content, we return name1 because the merged values match name1
        PropertyName merged = PropertyName.merge(name1, name2);
        assertSame(name1, merged);

        // Case 2: merged result is same as name2 -> return name2
        // How? If name1 has empty or null for both, then we use name2.
        PropertyName empty = new PropertyName("", "");
        PropertyName name3 = new PropertyName("non-empty", "ns");
        merged = PropertyName.merge(empty, name3);
        // The merged simple name is "non-empty", namespace is "ns" -> matches name3
        assertSame(name3, merged);

        // Case 3: merged result doesn't match either -> new instance
        PropertyName name4 = new PropertyName("combined", "");
        PropertyName name5 = new PropertyName("", "ns-combined");
        merged = PropertyName.merge(name4, name5);
        // For simple name: name4 has non-empty -> "combined"
        // For namespace: name4 has empty -> so we take name5's namespace -> "ns-combined"
        // Now, does this match name4? name4 has simple="combined", namespace="" -> no.
        // Does it match name5? name5 has simple="", namespace="ns-combined" -> no.
        // So we create a new instance.
        assertNotSame(name4, merged);
        assertNotSame(name5, merged);
        assertEquals("combined", merged.getSimpleName());
        assertEquals("ns-combined", merged.getNamespace());
    }

    @Test
    public void testHashCodeConsistency() {
