        assertEquals(p1.hashCode(), p2.hashCode());

        // Different namespace -> different hash code
        PropertyName p3 = new PropertyName("test", "other");
        assertNotEquals(p1.hashCode(), p3.hashCode());

        // Different simple name -> different hash code
        PropertyName p4 = new PropertyName("other", "ns");
        assertNotEquals(p1.hashCode(), p4.hashCode());
