package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.annotation.JsonDeserialize;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.module.SimpleModule;
import org.junit.Test;

import java.io.IOException;

import static org.junit.Assert.*;

public class BeanDeserializerCurrentValueTest {

    // Custom deserializer that relies on getCurrentValue()
    public static class ParentDeserializer extends StdDeserializer<Parent> {
        public ParentDeserializer() {
            super(Parent.class);
        }

        @Override
        public Parent deserialize(JsonParser p, DeserializationContext ctxt) throws IOException {
            Parent parent = new Parent();

            // Ensure we start with null current value
            assertNull(p.getCurrentValue());

            while (p.nextToken() != JsonToken.END_OBJECT) {
                String fieldName = p.currentName();
                p.nextToken();

                // Save current value and set to parent for nested deserialization
                Object oldValue = p.getCurrentValue();
                p.setCurrentValue(parent);

                if ("field1".equals(fieldName)) {
                    parent.field1 = p.readValueAs(Field1.class);
                } else if ("field2".equals(fieldName)) {
                    parent.field2 = p.readValueAs(Field2.class);
                }

                // Restore original current value
                p.setCurrentValue(oldValue);
            }

            return parent;
        }
    }

    // Custom deserializer for Field2 that uses getCurrentValue()
    public static class Field2Deserializer extends StdDeserializer<Field2> {
        public Field2Deserializer() {
            super(Field2.class);
        }

        @Override
        public Field2 deserialize(JsonParser p, DeserializationContext ctxt) throws IOException {
            Object currentValue = p.getCurrentValue();
            assertNotNull("Current value should not be null", currentValue);

            Field2 field2 = new Field2();
            if (p.currentToken() == JsonToken.START_OBJECT) {
                while (p.nextToken() != JsonToken.END_OBJECT) {
                    String fieldName = p.currentName();
                    p.nextToken();
                    if ("value".equals(fieldName)) {
                        field2.value = p.getText();
                    }
                }
            }
            return field2;
        }
    }

    // Test classes
    @JsonDeserialize(using = ParentDeserializer.class)
    public static class Parent {
        public Field1 field1;
        public Field2 field2;

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (!(obj instanceof Parent)) return false;
            Parent other = (Parent) obj;
            return java.util.Objects.equals(field1, other.field1) &&
                   java.util.Objects.equals(field2, other.field2);
        }

        @Override
        public int hashCode() {
            return java.util.Objects.hash(field1, field2);
        }
    }

    public static class Field1 {
        // Empty class for testing empty object
        @Override
        public boolean equals(Object obj) {
            return obj instanceof Field1;
        }

        @Override
        public int hashCode() {
            return 1;
        }
    }

    @JsonDeserialize(using = Field2Deserializer.class)
    public static class Field2 {
        public String value;

        @Override
