package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.PropertyNamingStrategies;
import com.fasterxml.jackson.databind.PropertyNamingStrategy;
import com.fasterxml.jackson.core.JsonProcessingException;
import org.junit.Test;
import static org.junit.Assert.*;

import java.util.*;

public class POJOPropertiesCollectorEnumNamingTest {

    // Test enum with a field that could conflict with naming strategy
    public enum TestEnumWithField {
        FOO(1),
        BAR(2);

        public final int value;

        TestEnumWithField(int value) {
            this.value = value;
        }
    }

    // Another test enum with snake_case field that would be renamed by SNAKE_CASE strategy
    public enum TestEnumWithSnakeField {
        FIRST_VALUE(10),
        SECOND_VALUE(20);

        public final int snake_field;

        TestEnumWithSnakeField(int val) {
            this.snake_field = val;
        }
    }

    // Enum with multiple fields
    public enum ComplexEnum {
        ITEM_A(1, "A"),
        ITEM_B(2, "B");

        public final int id;
        public final String name;

        ComplexEnum(int id, String name) {
            this.id = id;
            this.name = name;
        }
    }

    // Enum with no-args constructor (no fields that could conflict)
    public enum SimpleEnum {
        VALUE1,
        VALUE2,
        VALUE3
    }

    // Test enum that triggers the bug: field with same name as constant (case-insensitive)
    public enum EnumWithConflictingField {
        FOO(42);

        public final int foo;

        EnumWithConflictingField(int foo) {
            this.foo = foo;
        }
    }

    // Test enum with multiple fields that could conflict
    public enum MultiFieldEnum {
        VALUE_A(1, "a"),
        VALUE_B(2, "b");

        public final int valueA;
        public final String valueB;

        MultiFieldEnum(int valueA, String valueB) {
            this.valueA = valueA;
            this.valueB = valueB;
        }
    }

    // Static container class for enum-in-object test (with setter)
    static class Container {
        private TestEnumWithField enumField;
        public String name;

        public void setEnumField(TestEnumWithField value) {
            this.enumField = value;
        }

        public TestEnumWithField getEnumField() {
            return enumField;
        }
    }

    // Container class with collection of enums
    static class ContainerWithEnumCollection {
        public List<TestEnumWithField> enums;
        public String name;
    }

    @Test
    public void testEnumDeserializationWithPropertyNamingStrategy() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE);

        // Test deserialization of enum with field that could conflict
        TestEnumWithField result1 = mapper.readValue("\"FOO\"", TestEnumWithField.class);
        assertEquals(TestEnumWithField.FOO, result1);

        TestEnumWithField result2 = mapper.readValue("\"BAR\"", TestEnumWithField.class);
        assertEquals(TestEnumWithField.BAR, result2);

        // Test deserialization of enum with snake_case field
        TestEnumWithSnakeField result3 = mapper.readValue("\"FIRST_VALUE\"", TestEnumWithSnakeField.class);
        assertEquals(TestEnumWithSnakeField.FIRST_VALUE, result3);

        TestEnumWithSnakeField result4 = mapper.readValue("\"SECOND_VALUE\"", TestEnumWithSnakeField.class);
        assertEquals(TestEnumWithSnakeField.SECOND_VALUE, result4);

        // Test deserialization of complex enum
        ComplexEnum result5 = mapper.readValue("\"ITEM_A\"", ComplexEnum.class);
        assertEquals(ComplexEnum.ITEM_A, result5);

        ComplexEnum result6 = mapper.readValue("\"ITEM_B\"", ComplexEnum.class);
        assertEquals(ComplexEnum.ITEM_B, result6);
    }

    @Test
    public void testEnumSerializationWithPropertyNamingStrategy() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE);

        // Test serialization of enum values
        String json1 = mapper.writeValueAsString(TestEnumWithField.FOO);
        assertEquals("\"FOO\"", json1);

        String json2 = mapper.writeValueAsString(TestEnumWithSnakeField.SECOND_VALUE);
        assertEquals("\"SECOND_VALUE\"", json2);

        String json3 = mapper.writeValueAsString(ComplexEnum.ITEM_B);
        assertEquals("\"ITEM_B\"", json3);
    }

    @Test
    public void testEnumWithUpperCaseStrategy() throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        mapper.setPropertyNamingStrategy(PropertyNamingStrategies.UPPER_CAMEL_CASE);

        // Test that enum deserialization still works with different naming strategies
        TestEnumWithField result = mapper.readValue("\"FOO\"", TestEnumWithField.class);
