package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.annotation.JsonSetter;
import com.fasterxml.jackson.annotation.Nulls;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.PropertyName;
import com.fasterxml.jackson.databind.deser.NullValueProvider;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.impl.NullsConstantProvider;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.introspect.BeanPropertyDefinition;
import com.fasterxml.jackson.databind.introspect.POJOPropertyBuilder;
import org.junit.Test;

import java.io.IOException;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;

public class MethodPropertyTest {

    public static class Inner {
        public String field1;
    }

    public static class Middle {
        @JsonSetter(nulls = Nulls.SKIP)
        private List<Inner> list1 = new ArrayList<>();
        public String field1;

        public List<Inner> getList1() {
            return list1;
        }

        public void setList1(List<Inner> list1) {
            this.list1 = list1;
        }
    }

    public static class Outer {
        private List<Middle> list1;

        public List<Middle> getList1() {
            return list1;
        }

        public void setList1(List<Middle> list1) {
            this.list1 = list1;
        }
    }

    private MethodProperty createMethodProperty(ObjectMapper mapper, Method setter, boolean skipNulls) throws Exception {
        AnnotatedMethod annotatedMethod = new AnnotatedMethod(null, setter, null, null);
        BeanPropertyDefinition propDef = new POJOPropertyBuilder(
            mapper.getDeserializationConfig(), 
            mapper.getDeserializationConfig().getAnnotationIntrospector(), 
            true, 
            new PropertyName("list1")
        );
        MethodProperty methodProperty = new MethodProperty(
            propDef,
            mapper.constructType(List.class),
            null,
            null,
            annotatedMethod
        );

        // Use proper API to configure null handling
        if (skipNulls) {
            methodProperty = (MethodProperty) methodProperty.withNullProvider(NullsConstantProvider.skipper());
        } else {
            methodProperty = (MethodProperty) methodProperty.withNullProvider(NullsConstantProvider.nuller());
        }

        return methodProperty;
    }

    @Test
    public void testSetAndReturnWithSkipNulls() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        Method setter = Middle.class.getDeclaredMethod("setList1", List.class);
        MethodProperty methodProperty = createMethodProperty(mapper, setter, true);

        Middle middle = new Middle();
        Object result = methodProperty.setAndReturn(middle, null);

        assertSame(middle, result);
        assertNotNull(middle.getList1());
        assertTrue(middle.getList1().isEmpty());
    }

    @Test
    public void testSetWithSkipNulls() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        Method setter = Middle.class.getDeclaredMethod("setList1", List.class);
        MethodProperty methodProperty = createMethodProperty(mapper, setter, true);

        Middle middle = new Middle();
        methodProperty.set(middle, null);

        assertNotNull(middle.getList1());
        assertTrue(middle.getList1().isEmpty());
    }

    @Test
    public void testSetAndReturnWithoutSkipNulls() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        Method setter = Middle.class.getDeclaredMethod("setList1", List.class);
        MethodProperty methodProperty = createMethodProperty(mapper, setter, false);

        Middle middle = new Middle();
        Object result = methodProperty.setAndReturn(middle, null);

        assertSame(middle, result);
        assertNull(middle.getList1());
    }

    @Test
    public void testSetWithoutSkipNulls() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        Method setter = Middle.class.getDeclaredMethod("setList1", List.class);
        MethodProperty methodProperty = createMethodProperty(mapper, setter, false);

        Middle middle = new Middle();
        methodProperty.set(middle, null);

        assertNull(middle.getList1());
    }

    @Test
    public void testIntegrationWithJsonSetterAnnotation() throws IOException {
        String json = "{\"list1\": [{\"list1\": null, \"field1\": \"data\"}]}";
        ObjectMapper mapper = new ObjectMapper();
        Outer outer = mapper.readValue(json, Outer.class);

        assertNotNull(outer.getList1());
        assertEquals(1, outer.getList1().size());

        Middle middle = outer.getList1().get(0);
        assertNotNull(middle.getList1());
        assertTrue(middle.getList1().isEmpty());
        assertEquals("data", middle.field1);
    }

    @Test
    public void testSetAndReturnWithNonNullValue() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        Method setter = Middle.class.getDeclaredMethod("setList1", List.class);
        MethodProperty methodProperty = createMethodProperty(mapper, setter, true);

        Middle middle = new Middle();
