    public static class Inner {
        public String field1;
    }

    public static class Middle {
        @JsonSetter(nulls = Nulls.SKIP)
        private List<Inner> list1 = new ArrayList<>();
        public String field1;

        public List<Inner> getList1() {
            return list1;
        }

        public void setList1(List<Inner> list1) {
            this.list1 = list1;
        }
    }

    public static class Outer {
        private List<Middle> list1;

        public List<Middle> getList1() {
            return list1;
        }

        public void setList1(List<Middle> list1) {
            this.list1 = list1;
        }
    }

    private MethodProperty createMethodProperty(ObjectMapper mapper, Method setter, boolean skipNulls) throws Exception {
        AnnotatedMethod annotatedMethod = new AnnotatedMethod(null, setter, null, null);
        BeanPropertyDefinition propDef = new POJOPropertyBuilder(
            mapper.getDeserializationConfig(), 
            mapper.getDeserializationConfig().getAnnotationIntrospector(), 
            true, 
            new PropertyName("list1")
        );
        MethodProperty methodProperty = new MethodProperty(
            propDef,
            mapper.constructType(List.class),
            null,
            null,
            annotatedMethod
        );

        // Use proper API to configure null handling
        if (skipNulls) {
            methodProperty = (MethodProperty) methodProperty.withNullProvider(NullsConstantProvider.skipper());
        } else {
            methodProperty = (MethodProperty) methodProperty.withNullProvider(NullsConstantProvider.nuller());
        }

        return methodProperty;
    }

